pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }
    // Small but potentially usable gaps: soft penalty proportional to unusability.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Open-bin pressure: prefer using existing bins over opening new ones.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if the next item fits in the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    }
    // Penalize leaving a gap that nearly fits but not quite for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Avoid wasting nearly-full bins; prefer filling large-residual bins with big items.
    score -= (bin_residual - item_size.min(bin_residual)) as f64 * 0.5;

    // Mild drift: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let r = post_residual;

    // Fill ratio of this placement: strongly reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.95 {
        score -= 20.0;
    } else if fill_ratio > 0.85 {
        score -= 8.0;
    }

    if r == 0 {
        score -= 950.0; // perfect fit
    } else if r < 10 {
        score += 65.0; // dead space below min item
    } else {
        if r % 10 == 0 {
            score -= 14.0;
        } else if r % 25 == 0 {
            score -= 10.0;
        } else if r % 5 == 0 {
            score -= 4.0;
        } else {
            score += 9.0;
        }
        // Mid-range residuals are highly usable by typical item sizes.
        if r >= 15 && r <= 45 {
            score -= 7.0;
        }
        // Penalize residuals too small for the upcoming item.
        if r < next_item_size {
            score += (next_item_size - r) as f64 * 3.0;
        }
    }

    // Fill-level coupling: reward near-closed bins.
    let fill = (bin_residual as f64) / cap;
    if fill >= 0.92 {
        score -= 26.0;
    } else if fill >= 0.9 {
        score -= 20.0;
    } else if fill >= 0.7 {
        score -= 9.0;
    } else if fill < 0.28 {
        score += 9.0;
    }

    // Lookahead couplings with graded rewards.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = r as f64;
        if pr == nxt {
            score -= 390.0;
            if fitting_bins_count <= 3 {
                score -= 40.0;
            }
        } else if pr >= nxt && pr - nxt <= 10.0 {
            score -= 145.0;
            if pr - nxt <= 8.0 {
                score -= 80.0;
            }
            if pr - nxt <= 3.0 {
                score -= 70.0;
            }
        } else if r > 0 && r < next_item_size {
            score += (nxt - pr) * 5.0;
        } else if pr >= nxt && (r - next_item_size) % 10 == 0 {
            score -= 26.0;
        }
        if pr >= nxt && pr - nxt >= 20.0 {
            score -= 10.0;
        }
        // Penalize leaving a gap that is too large to be useful but not reusable.
        if pr > nxt && pr - nxt > 10.0 && pr - nxt < (nxt * 0.5).max(8.0) {
            score += 15.0;
        }
        if pr > 0.0 && pr < nxt * 0.35 {
            score += 7.0;
        }
        if pr > 0.0 && pr < nxt * 0.6 && pr >= nxt * 0.35 {
            score += 11.0;
        }
        // Two-item lookahead: residual that fits exactly two of the next item.
        if pr >= nxt && (pr - nxt) as u32 % next_item_size == 0 && pr - nxt > 0.0 {
            score -= 12.0;
        }
    }

    // Deviation from fleet mean: prefer bins that consolidate spare space.
    score += (mean_residual - bin_residual as f64) * 1.5;

    // Waste ratio of this placement.
    if item_size > 0 {
        let waste_ratio = r as f64 / (r + item_size) as f64;
        score += waste_ratio * 20.0;
    }

    // Last-chance / scarce-bin pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if fitting_bins_count <= 2 && r >= next_item_size && r > 0 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening unless bins are nearly full or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_fill = 1.0 - mean_residual / cap;
        if avg_open_fill < 0.65 && progress > 0.08 {
            score += 55.0;
        } else {
            score += 12.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 55.0;
        }
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.6 {
            score -= 30.0;
        }
        if total_items.saturating_sub(step_index) > 200 && open_bins_count < 12 {
            score -= 12.0;
        }
        if next_item_size as f64 > mean_residual * 1.4 && total_items.saturating_sub(step_index) > 100 {
            score -= 9.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
