        // small unusable fraction of capacity, scaled by how many open bins
        // already exist (fragmentation pressure).
        if pr > 0.0 && pr < 12.0 && open_bins_count > 2 {
            score += 6.0 + 0.8 * open_bins_count as f64;
        }
    }

