    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps below the minimum item size are pure waste: hard penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, huge reward
    } else {
        // Penalize gaps that are too small for plausible future items.
        // A gap is "dead" if it cannot fit the next item (when known)
        // or is in the awkward small-gap band.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 3.0;
            } else {
                // Gap usable by next item: mild reward proportional to usability
                score -= 2.0;
            }
        }
        // Small-gap band penalty: gaps < 15 are rarely reusable
        if post_residual < 15 {
            score += (15 - post_residual) as f64 * 4.0;
        }
        // Gaps in 15..40 are moderately risky (only small/medium items fit)
        if post_residual >= 15 && post_residual < 40 {
            score += 5.0;
        }
        // Large usable gaps are good (keep bins flexible)
        if post_residual >= 50 {
            score -= 6.0;
        }
    }

    // --- Open bins pressure ---
    // Discourage opening new bins when many bins are already open,
    // but allow it when few bins are open and fit is poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize so we only open when fits are truly bad
        score += 25.0 + bin_pressure * 2.0;
        // But if the item is huge relative to typical residual, opening fresh
        // can be better than fragmenting a half-full bin.
        if item_size as f64 > mean_residual * 0.8 && mean_residual > 0.0 {
            score -= 18.0;
        }
    }

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Only this bin fits: strongly prefer it over opening a new bin
        score -= 30.0;
    }

    // --- Mean residual coupling ---
    // If this bin's residual is far below the mean, it's a "straggler" bin:
    // prefer filling it to consolidate open bins.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.3;
    } else {
        score += (-residual_gap) * 0.1;
    }

    // --- Tight fit reward ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - progress) + x * (1.0 - x).powi(3) * progress;
    let mut score = post - 40.0 * poly * cap;

    // Reward tight fits smoothly (quartic in normalized fit quality)
    let fit_quality = 1.0 - x;
    score -= 25.0 * fit_quality * fit_quality * fit_quality * fit_quality;

    // Penalize dead space relative to mean residual, scaled by openness
    score += 0.05 * (post - mean_residual).abs() * (open_bins_count as f64).ln();

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fit_quality;
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            score += 8.0 * (nxt - post) / cap * (1.0 - progress);
        } else {
            score -= 6.0 * (1.0 - (post - nxt) / cap) * progress;
        }
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual as f64 == cap {
        score += 20.0 * (1.0 - progress) + 5.0;
    }

    score
}

