    score += bucket as f64 * 3.0;

    // Lookahead coupling: reward if next_item_size fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post < 10 { score += 5.0; } // chains into near-dead space
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this residual; residual value drops.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Modulo arithmetic on residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) are more reusable.
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }
    }

    // New-bin candidate: only attractive early in the stream or when existing
    // residual is badly fragmented (mean_residual high but this bin poor fit).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 * 2.0;
        let fragmentation = (mean_residual - post_frac * 100.0).abs();
        score += 30.0 + open_pressure + progress * 40.0 - fragmentation * 0.2;
        // Empty-bin base score: neutral-ish, high enough that good fits win.
        score += post_residual as f64 * 0.5;
    }

    // Late stream: consolidate, penalize opening spread across many bins.
    if open_bins_count > 8 {
        score += post_frac * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals in the "unusable gap" band (1..=20)
    // are disproportionately harmful because few future items fit there.
    if post_residual > 0 && post_residual <= 20 {
        score += (21 - post_residual) as f64 * 3.0;
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 2.0 * (0.5 + progress);

    // Lookahead: if the next item can use the leftover space, reward this placement;
    // if the leftover is smaller than the next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Slight preference for bins tighter than the current average residual.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect / near-perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when the leftover space matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 300.0; // perfect chaining into next item
        } else if pr >= nxt && pr - nxt <= 10.0 {
            score -= 120.0; // next item fits snugly
        } else if pr > 0.0 && pr < nxt {
            // leftover too small for next item: dead space, penalize proportionally
            score += (nxt - pr) * 4.0;
        }
        // Bonus if after placing next item too the bin would be near-full
        if pr >= nxt && pr - nxt <= 8.0 {
            score -= 80.0;
        }
    } else {
        // Last item: prefer minimizing leftover hard.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Compare against mean residual: bins tighter than average are more valuable.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 1.5; // favor bins with below-average residual (tight bins)

    // Penalize wasting a large bin on a small item (large post_residual relative to item).
    if item_size > 0 {
        let waste_ratio = post_residual as f64 / (post_residual + item_size) as f64;
        score += waste_ratio * 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // base penalty so new bins aren't opened casually
        score += 150.0;
        // if item is large relative to capacity, opening fresh bin is more reasonable
        score -= item_size as f64 * 0.8;
        // if many bins fit the item, keep using them instead
        if fitting_bins_count > 1 {
            score += 100.0;
        }
        // early in the stream, opening bins is cheaper (more future items to fill it)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 60.0;
        // if next item is large, a fresh bin gives flexibility
        if next_item_size >= item_size {
            score -= 40.0;
        }
    }

    // Mild penalty per open bin to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically, but only if truly unusable later.
    let dead = post_residual as f64;
    let small_threshold = 10.0;
    if dead > 0.0 && dead < small_threshold {
        score += 40.0 * (small_threshold - dead) / small_threshold;
    }

    // Reward tight fits (low post_residual relative to item).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Lookahead: if next item fits into post_residual, big bonus.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 25.0;
        // Extra reward if next item exactly fills the bin.
        if next_item_size as u32 == post_residual {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize wasted residual relative to next item.
        let gap = post_residual as f64 - (next_item_size as f64).min(bin_capacity as f64);
        if gap > 0.0 {
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in stream, be conservative about dead space (many items remain);
    // later, prefer filling existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * (1.0 - progress) * (dead / bin_capacity as f64);
    score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer consolidating
    // into bins with residual near mean (avoid fragmenting).
    if open_bins_count > 3 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev * (open_bins_count as f64).ln();
    }

    // New-bin candidate: make it unattractive unless post_residual is perfectly empty
    // or no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && (bin_capacity as f64 - item_size as f64) > 0.0;
        if decent_fit_exists {
            score += 60.0;
            // Allow new bin late in stream if current bin residuals are all tiny.
            if progress > 0.8 && mean_residual < item_size as f64 * 0.5 {
                score -= 55.0;
            }
        } else {
            score -= 10.0;
        }
        // Empty bin with lookahead item equal to item_size: reserve for pairing.
        if next_item_size == item_size {
            score += 20.0;
        }
    }

    // Mild penalty for leaving residual exactly equal to common small sizes (dead space risk).
    for r in [1u32, 2, 3, 4, 5] {
        if post_residual == r {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with a non-linear convex
    // penalty that grows superlinearly for large leftover space.
    let mut score = post + 12.0 * norm_post * norm_post * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, tolerate slack (bins stay reusable later);
    // late in the stream, demand tight packing.
    let coupling = progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score -= 8.0 * coupling * norm_post;              // mid-stream: slack is less costly
    score += 20.0 * progress * progress * norm_post;  // late: heavily penalize slack

    // Dead-space shaping: residuals too small for typical items are wasteful.
    let dead = (norm_post - (item_size as f64 / cap)).max(0.0);
    score += 6.0 * dead * dead * cap;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward a bin whose post-residual can still host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Mild pressure against accumulating many open bins with slack.
    score += 0.05 * open_bins_count as f64 * norm_post;
    score += 0.5 * (mean_residual - post).abs() / cap;

    // New-bin candidate: keep it neutral-to-slightly-early, discourage late.
    if bin_residual == bin_capacity {
        score += 3.0 + 30.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity / 4 buckets
    let item_class = item_size / (bin_capacity / 4).max(1);
    let next_class = next_item_size / (bin_capacity / 4).max(1);

    // Reward tight fits (post_residual small), strongly for small post_residual
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Dead space penalty: post_residual too small for the smallest possible item
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Harmonic compatibility: reward when next item's class fits into post_residual class-wise
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits exactly into this bin's leftover
        let harmony = (post_residual - next_item_size) as f64;
        score -= 20.0 - harmony * 0.5;
        // extra reward if classes align (same harmonic class)
        if item_class == next_class {
            score -= 8.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this leftover: penalize large leftovers that go to waste
        score += (post_residual as f64) * 0.15;
    }

    // Modulo-based pairing logic: item sizes summing to multiples of half-capacity are ideal
    if next_item_size > 0 && (item_size + next_item_size) % (bin_capacity / 2) == 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize unless current bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        } else if avg_pressure < 25.0 {
            // open bins still have plenty of room: opening new bin wastes capacity
            score += 40.0;
        } else {
            score += 10.0; // mild default penalty
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild bonus for filling bins that are already partially used (reduce bin count)
    if bin_residual < bin_capacity {
        let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_frac * 10.0;
    }

    // Prefer bins with residual near mean residual (keeps bin balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are >= 1, but typical item sizes make tiny gaps worthless).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> strong penalty
    } else if post_residual < 20 {
        score += 15.0; // poor gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill: heavily reward
    }

    // Reward tight fits (high fill ratio of the residual).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless the fit is excellent.
    score += 2.5 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New empty bin candidate: neutral baseline, only attractive when the
    // item fits poorly everywhere else. Penalize mildly so existing bins win ties.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening a new bin is more attractive late in the stream is false;
        // keep it steady but scale with how bad mean residual spread is.
        if (mean_residual - post_residual as f64).abs() < 5.0 {
            score -= 10.0; // new bin keeps residuals uniform
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slightly prefer bins whose
        // post residual stays useful for the next item.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover exactly hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 200.0 - gap * 1.5;
        // Exact two-item closure (item + next fills bin completely).
        if post_residual == next_item_size {
            score -= 800.0;
        }
    } else if next_item_size > 0 {
        // Leftover cannot host next item: penalize dead space, worse if tiny.
        let waste = post_residual as f64;
        if waste > 0.0 && waste < 10.0 {
            score += 150.0;
        }
        score += waste * 0.3;
    }

    // Coupling with mean residual: prefer bins whose post-residual is near the mean
    // (keeps bin profile balanced), penalize extreme outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when existing bins would leave large waste.
    if bin_residual == bin_capacity {
        let best_case = 100.0 - (post_residual as f64).max(0.0);
        // Opening a new bin is penalized progressively as stream progresses / bins accumulate.
        let late = step_index as f64 / (total_items.max(1) as f64);
        score += 250.0 + 100.0 * late + 0.5 * open_bins_count as f64;
        // But if this item barely fits anywhere (huge item), new bin becomes reasonable.
        if item_size >= 70 {
            score -= 200.0;
        }
        let _ = best_case;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of capacity wasted by this placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;

    // Perfect fit gets a strong reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            // leftover too small for next item: penalize proportionally to dead space
            score += 4.0 * waste_frac;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: empty bin gets a baseline cost that shrinks
    // as the stream progresses (later on, prefer reusing open bins more strongly)
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (1.0 - progress);
        // but if the fit in any open bin would be terrible, new bin is attractive
        if waste_frac > 0.5 {
            score -= 30.0;
        }
    }

    // Penalize bins far from mean residual (prefer bins whose residual is typical)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Mild diversity pressure: many open bins -> prefer tighter fills
    score += 0.5 * open_bins_count as f64 * waste_frac;

    // Small time-decay on absolute residual so late stream favors tight packing
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, non-linearly (quadratic coupling)
    let mut score = post * (1.0 + 0.9 * pr * pr);

    // Smooth polynomial coupling with stream progress:
    // early on, mild penalty for post residual; later, stronger (waste matters more)
    let prog_coupling = 1.0 + 1.4 * progress * progress + 0.8 * progress * pr;
    score *= prog_coupling;

    // Perfect-ish fit reward (smooth, no hard cutoff)
    let fit_bonus = 18.0 * (1.0 - pr) * (1.0 - pr) * (1.0 + 0.5 * progress);
    score -= fit_bonus;

    // Last chance bin: reward strongly when few fitting bins (smooth ramp)
    let last_chance = if fitting_bins_count >= 1 {
        1.0 / fitting_bins_count as f64
    } else {
        1.0
    };
    score -= 10.0 * last_chance * (1.0 + progress);

    // Lookahead: reward if next item fits into resulting post residual (smooth falloff)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 14.0 * (1.0 - slack * slack) * (1.0 + 0.6 * progress);
        } else {
            // penalty proportional to how badly it misses, smoothed
            let miss = (nxt - post) / cap;
            score += 6.0 * miss * (1.0 - progress);
        }
    }

    // Deviation from mean residual: prefer bins whose residual is below/at mean
    // (pack tighter bins first), smooth quadratic penalty
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for spreading across many open bins late in stream
    score += 0.35 * open_bins_count as f64 * progress * progress;

    // New-bin candidate: make empty bin attractive only when it avoids bad fits;
    // smooth barrier: empty bin gets baseline score scaled by progress
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.45 * progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by integer division.
    // Classes: 0 (perfect fit), 1..10 (tight), 11..20 (usable), >20 (dead zone).
    let pr = post_residual;
    let class = pr / 10; // harmonic bucket of size 10
    match class {
        0 => {
            // Perfect or near-perfect fit: heavily reward.
            score -= 30.0;
            // Exact zero residual is ideal.
            if pr == 0 { score -= 15.0; }
        }
        1 => {
            // Residual 10..19: still usable for typical small items (1..10 exists).
            score -= 8.0;
            // Bonus if next item can exploit it exactly.
            if next_item_size > 0 && next_item_size <= pr {
                score -= 6.0;
            }
        }
        2 => {
            // Residual 20..29: moderately usable.
            if next_item_size > 0 && next_item_size <= pr {
                score -= 4.0;
            } else {
                score += 5.0;
            }
        }
        3..=4 => {
            // Residual 30..49: dead-zone risk, penalize unless next item fits.
            if next_item_size > 0 && next_item_size <= pr {
                score -= 3.0;
            } else {
                score += 12.0;
            }
        }
        _ => {
            // Residual >= 50: wasteful split; strong penalty.
            score += 20.0 + (pr as f64) * 0.1;
        }
    }

    // Modulo coupling: reward when post_residual aligns with common size classes
    // (multiples of 5 and 10 are likely to be re-filled).
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, scaled by how tight the fit is.
    if fitting_bins_count == 1 {
        let tightness = 1.0 - (pr as f64) / (bin_capacity as f64);
        score -= 10.0 + 15.0 * tightness;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = (bin_capacity as f64) * 0.9;
        // More attractive early in the stream (plenty of items left to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // Less attractive if many bins already open (consolidate instead).
        score += open_bins_count as f64 * 2.0;
        // If next item is large, a fresh bin is valuable for pairing.
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Slight preference for bins below mean residual (keeps balance,
    // preserves larger residuals for larger future items).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    // Lookahead synergy: reward if next item pairs perfectly with post_residual.
    if next_item_size > 0 && next_item_size == pr {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps below the minimum item size are pure waste: hard penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, huge reward
    } else {
        // Penalize gaps that are too small for plausible future items.
        // A gap is "dead" if it cannot fit the next item (when known)
        // or is in the awkward small-gap band.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 3.0;
            } else {
                // Gap usable by next item: mild reward proportional to usability
                score -= 2.0;
            }
        }
        // Small-gap band penalty: gaps < 15 are rarely reusable
        if post_residual < 15 {
            score += (15 - post_residual) as f64 * 4.0;
        }
        // Gaps in 15..40 are moderately risky (only small/medium items fit)
        if post_residual >= 15 && post_residual < 40 {
            score += 5.0;
        }
        // Large usable gaps are good (keep bins flexible)
        if post_residual >= 50 {
            score -= 6.0;
        }
    }

    // --- Open bins pressure ---
    // Discourage opening new bins when many bins are already open,
    // but allow it when few bins are open and fit is poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize so we only open when fits are truly bad
        score += 25.0 + bin_pressure * 2.0;
        // But if the item is huge relative to typical residual, opening fresh
        // can be better than fragmenting a half-full bin.
        if item_size as f64 > mean_residual * 0.8 && mean_residual > 0.0 {
            score -= 18.0;
        }
    }

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Only this bin fits: strongly prefer it over opening a new bin
        score -= 30.0;
    }

    // --- Mean residual coupling ---
    // If this bin's residual is far below the mean, it's a "straggler" bin:
    // prefer filling it to consolidate open bins.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.3;
    } else {
        score += (-residual_gap) * 0.1;
    }

    // --- Tight fit reward ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Bin can host the lookahead item too: reward closeness of match.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Lookahead item won't fit in the leftover: penalize dead space,
            // worse when the dead space is small-but-unusable.
            score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Reward tight packing relative to the fleet mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin guarantees a clean home for lookahead
        }
    }

    // Late in the stream: consolidate harder, avoid leaving scattered residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly; small residuals are fine.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose leftover can host the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 10.0 + 15.0 * tightness;
    } else if next_item_size > 0 {
        // Leftover useless for next item: penalize proportionally to dead space.
        score += next_item_size as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; prefer tight bins.
    let crowd = open_bins_count as f64 / (1.0 + total_items as f64 / 10.0);
    score += crowd * (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Time horizon: early on, be selective (penalize loose fits); late, pack greedily.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * (bin_residual as f64 - item_size as f64).max(0.0) * 0.2;
    score -= t * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global residual pressure: if mean residual is low, opening new bins is costly.
    if mean_residual < item_size as f64 && bin_residual == bin_capacity {
        score += 15.0;
    } else if mean_residual > item_size as f64 * 2.0 && bin_residual == bin_capacity {
        score -= 8.0; // plenty of slack elsewhere? actually prefer reusing; slight penalty for new bin
    }

    // New-bin candidate baseline: keep it moderately expensive so it's chosen only for poor fits.
    if bin_residual == bin_capacity {
        score += item_size as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic waste penalty on post-residual (dead space grows quadratically).
    let mut score = post + (post * post) / (2.0 * cap);

    // Tight fit reward: smooth bell around post_residual -> 0.
    let tightness = (post / cap).powi(2);
    score -= cap * (1.0 - tightness) * 0.5;

    // Stream-progress coupling: early on, prefer filling bins loosely (keep flexibility);
    // later, reward aggressive filling. Smooth polynomial in progress.
    let p = progress;
    let aggressiveness = 3.0 * p * p - 2.0 * p * p * p; // smoothstep in [0,1]
    score -= aggressiveness * post * 0.6;

    // Penalize bins that are already very full relative to mean residual (preserve spread).
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / cap;
        score += 0.8 * rel * rel * cap * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // Mild congestion penalty: many fitting bins -> prefer tighter ones anyway.
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Lookahead coupling: if next item fits in post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let nxt = next_item_size as f64;
        score -= 10.0 * (nxt / cap) * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving awkward remainder.
        score += 8.0 * (post / cap);
    }

    // New-bin candidate: make it moderately attractive only when progress is low
    // or no good fit exists; smooth in progress.
    if bin_residual == bin_capacity {
        let open_bonus = (open_bins_count as f64).ln().max(0.0) * 4.0;
        score += 25.0 + open_bonus * (1.0 - aggressiveness) - 30.0 * aggressiveness;
        if fitting_bins_count == 1 {
            score += 60.0; // don't open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by 10 or 25 is
    // reusable by common item sizes; odd small residuals are dead space.
    let r = post_residual;
    if r == 0 {
        score -= 40.0; // perfect fit, best outcome
    } else if r < 10 {
        score += 60.0; // unusable dead space (< min item)
    } else if r % 10 == 0 {
        score -= 12.0; // highly reusable class
    } else if r % 25 == 0 {
        score -= 8.0;  // reusable class
    } else if r % 5 == 0 {
        score -= 3.0;  // moderately reusable
    } else {
        score += 8.0;  // awkward residual
    }

    // Fractional fill level coupling: reward bins that become well-filled.
    let fill = (bin_residual as f64) / cap;
    if fill >= 0.9 {
        score -= 15.0;
    } else if fill >= 0.7 {
        score -= 7.0;
    } else if fill < 0.3 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 35.0;
        } else if next_item_size <= r && (r - next_item_size) % 10 == 0 {
            score -= 18.0;
        } else if next_item_size > r {
            score += 10.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless existing bins are
    // nearly full or the stream is early (diversity of open bins helps).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_fill = 1.0 - mean_residual / cap;
        if avg_open_fill < 0.6 && progress > 0.1 {
            score += 45.0; // keep using existing bins
        } else {
            score += 10.0; // mild preference for consolidation
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 {
        // Reward leaving a gap that can still host small items (>=10).
        score -= 5.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the post gap, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item cannot fit into the resulting gap, mild penalty for wasting the gap.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: prefer reusing existing bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless residuals across open bins are tiny.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        if mean_residual < item_size as f64 {
            // No open bin can meaningfully absorb; opening a new bin is justified.
            score -= 55.0;
        }
    }

    // Mild stream-progress term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.5;
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use.
        score += next_item_size as f64 * 0.3;
    }

    // Perfect fill bonus (post_residual zero means bin exactly closed).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize large unusable residual (waste) relative to mean residual.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < mean_residual {
            score -= 5.0;
        } else {
            score += (pr - mean_residual) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bin residual is very tight.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Allow new bin when existing residual is awkwardly small relative to item.
        if (bin_residual - item_size) > 0 && post_residual < 10 {
            score -= 55.0;
        }
    }

    // Late in stream: prefer closing bins tightly (less fragmentation left behind).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.05 + 0.15 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * item_size as f64;
    }

    // Lookahead: reward leaving room for the next item (chain-friendly placement).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: placing into a bin far below mean residual
    // (small residual bin) preserves larger spaces elsewhere.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Late in the stream, consolidation matters more: reward using existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        // New-bin candidate: base cost plus penalty growing with open bins and progress.
        score += 20.0 + 2.0 * open_bins_count as f64 + 30.0 * progress;
        // Opening a new bin is more acceptable for large items that fit poorly elsewhere.
        score -= 0.2 * item_size as f64;
    }

    // Mild penalty for leaving awkward residuals (small but nonzero leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling existing bins (penalize leftover more as stream advances).
    let norm_post = post / cap;
    let coupling = norm_post * norm_post * (0.5 + progress) + norm_post * (1.0 - progress) * 0.3;
    score += coupling * cap * 0.5;

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * cap * 0.4;

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.6;
    }

    // New-bin candidate handling: opening a bin wastes residual spread across open bins.
    if bin_residual == bin_capacity {
        // Penalize opening new bins when existing bins fit well (post small relative to item).
        let waste = (post - item_size as f64).max(0.0);
        score += cap * 0.25 + waste * 0.2;
        // Late in the stream, opening new bins is more acceptable (fewer future items to strand).
        score -= progress * cap * 0.35;
        // If no open bin fits tightly, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= cap * 0.5;
        }
    }

    // Lookahead: penalize leaving a residual that can't hold the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx && post > 0.0 {
            // dead space relative to next item, smooth penalty
            score += (nx - post) * 0.35 * (0.5 + progress);
        } else if post >= nx {
            // reward residual that exactly accommodates the next item
            let fit_q = 1.0 - ((post - nx) / cap).abs();
            score -= fit_q * fit_q * cap * 0.2;
        }
    }

    // Mild pressure toward consolidation when many bins are open.
    score += (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class boundaries via integer division on capacity fractions.
    let quarter = bin_capacity / 4;      // 25
    let eighth = bin_capacity / 8;       // 12

    // Penalize dead space in the "useless" band: post_residual too small to
    // hold any realistic future item, but not zero.
    if post_residual > 0 && post_residual < eighth {
        score += 40.0;
    }

    // Reward post-residuals that fall on harmonic class boundaries (multiples
    // of quarter/eighth) — these are friendly landing zones for future items.
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % eighth == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with
    // typical item sizes; reward them.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: strong reward, scaled by how cleanly it fits
            // (integer-division threshold on the pair).
            let chain_slack = post_residual - next_item_size;
            score -= 25.0;
            if chain_slack % 10 == 0 {
                score -= 8.0;
            }
            if chain_slack < eighth {
                score += 10.0; // near-perfect chain but leaves tiny crumb
            }
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // Next item would have fit BEFORE this placement but not after:
            // we destroyed a future option; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item is
    // huge relative to capacity or open bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 55.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size * 4 >= bin_capacity * 3 {
            score -= 70.0; // big items deserve fresh bins
        }
        if mean_residual < item_size as f64 && open_bins_count > 0 {
            score -= 45.0 * (1.0 - progress); // early stream: prefer fresh bins when nothing fits well
        }
    }

    // Mild pressure to consolidate: prefer bins tighter than the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

