pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let r = post_residual;

    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.95 {
        score -= 22.0;
    } else if fill_ratio > 0.85 {
        score -= 9.0;
    } else if fill_ratio > 0.75 {
        score -= 3.0;
    }

    if r == 0 {
        score -= 950.0;
    } else if r < 10 {
        score += 70.0;
    } else {
        if r % 10 == 0 {
            score -= 15.0;
        } else if r % 25 == 0 {
            score -= 11.0;
        } else if r % 5 == 0 {
            score -= 4.0;
        } else {
            score += 10.0;
        }
        if r >= 15 && r <= 45 {
            score -= 7.0;
        }
        if r < next_item_size {
            score += (next_item_size - r) as f64 * 3.0;
        }
    }

    let fill = (bin_residual as f64) / cap;
    if fill >= 0.92 {
        score -= 28.0;
    } else if fill >= 0.9 {
        score -= 21.0;
    } else if fill >= 0.7 {
        score -= 9.0;
    } else if fill < 0.28 {
        score += 9.0;
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = r as f64;
        if pr == nxt {
            score -= 390.0;
            if fitting_bins_count <= 3 {
                score -= 40.0;
            }
        } else if pr >= nxt && pr - nxt <= 10.0 {
            score -= 145.0;
            if pr - nxt <= 8.0 {
                score -= 80.0;
            }
            if pr - nxt <= 3.0 {
                score -= 70.0;
            }
        } else if r > 0 && r < next_item_size {
            score += (nxt - pr) * 5.0;
        } else if pr >= nxt && (r - next_item_size) % 10 == 0 {
            score -= 26.0;
        }
        if pr >= nxt && pr - nxt >= 20.0 {
            score -= 10.0;
        }
        if pr > nxt && pr - nxt > 10.0 && pr - nxt < (nxt * 0.5).max(8.0) {
            score += 15.0;
        }
        if pr > 0.0 && pr < nxt * 0.35 {
            score += 7.0;
        }
        if pr > 0.0 && pr < nxt * 0.6 && pr >= nxt * 0.35 {
            score += 11.0;
        }
        if pr >= nxt && (pr - nxt) as u32 % next_item_size == 0 && pr - nxt > 0.0 {
            score -= 13.0;
        }
        if pr >= nxt && pr - nxt >= nxt && pr - nxt < 2.0 * nxt + 6.0 {
            score -= 22.0;
        }
        if pr > nxt * 1.5 && pr < nxt * 2.0 {
            score += 6.0;
        }
        if nxt > 0.0 && pr >= nxt && (pr as u32) % next_item_size == 0 {
            let k = (pr as f64 / nxt).round();
            if k >= 2.0 && k <= 4.0 {
                score -= 18.0 + 6.0 * (4.0 - k);
            }
        }
        if pr > nxt && pr - nxt > 0.0 && pr - nxt < 10.0 {
            score -= 6.0;
        }
        if pr > 0.0 && pr < nxt {
            score += (nxt - pr) * 2.0;
        }
        if pr >= 10.0 && pr <= 60.0 && (r % 5 == 0) {
            score -= 5.0;
        }
        // dead-space coupling: tiny unusable residuals penalized more with many bins open
        if pr > 0.0 && pr < 12.0 && open_bins_count > 2 {
            score += 6.0 + 0.8 * open_bins_count as f64;
        }
        // dead-space penalty: residual too small to ever be useful again
        if pr > 0.0 && pr < 8.0 && nxt > pr {
            score += 14.0 + 2.0 * (8.0 - pr);
        }
        // reward leaving exactly a small-item-friendly gap
        if pr >= nxt && pr - nxt <= 2.0 {
            score -= 25.0;
        }
        // penalize residuals that cannot fit next item but are large enough to be wasted
        if pr >= nxt * 0.7 && pr < nxt {
            score += 6.0;
        }
        // consolidation: residual close to fleet mean is reusable by like items
        if pr > 0.0 && (pr - mean_residual).abs() < 4.0 && pr >= nxt {
            score -= 8.0;
        }
        // reward leaving a residual the next item can fill almost exactly, scaled by scarcity
        if pr > nxt && pr - nxt <= 5.0 && fitting_bins_count <= 4 {
            score -= 12.0 + 3.0 * (5.0 - (pr - nxt));
        }
    }

    score += (mean_residual - bin_residual as f64) * 1.5;

    if item_size > 0 {
        let waste_ratio = r as f64 / (r + item_size) as f64;
        score += waste_ratio * 20.0;
    }

    score += 2.2 * open_bins_count as f64 * (1.0 - fill_ratio);

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if fitting_bins_count <= 2 && r >= next_item_size && r > 0 {
        score -= 12.0;
    }

    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_fill = 1.0 - mean_residual / cap;
        if avg_open_fill < 0.65 && progress > 0.08 {
            score += 55.0;
        } else {
            score += 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 55.0;
        }
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.6 {
            score -= 30.0;
        }
        if open_bins_count > 3 {
            score += 8.0;
        }
        if total_items.saturating_sub(step_index) > 200 && open_bins_count < 12 {
            score -= 12.0;
        }
        if (mean_residual - r as f64).abs() < 5.0 {
            score -= 10.0;
        }
        if next_item_size as f64 >= cap * 0.9 {
            score -= 15.0;
        }
        if next_item_size as f64 > mean_residual * 1.4 && total_items.saturating_sub(step_index) > 100 {
            score -= 9.0;
        }
        if next_item_size <= item_size && item_size as f64 >= cap * 0.5 {
            score -= 25.0;
        }
        let any_fits_next = fitting_bins_count > 0 && mean_residual >= next_item_size as f64;
        if !any_fits_next && next_item_size > 0 && open_bins_count > 0 {
            score -= 18.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 24.0;
        }
        let remaining = total_items.saturating_sub(step_index);
        if remaining < 50 && open_bins_count > 0 {
            score += 35.0;
        }
        if remaining > 300 && open_bins_count > 6 && mean_residual > item_size as f64 * 1.2 {
            score += 14.0;
        }
        if remaining > 400 && open_bins_count < 4 {
            score -= 20.0;
        }
        // late-stream squeeze: force remaining items into existing residual space
        if remaining < 150 && open_bins_count > 0 {
            score += 25.0 + 0.2 * open_bins_count as f64;
        }
        // fragmentation guard: push consolidation when bins are half-empty
        if mean_residual > cap * 0.45 && open_bins_count > 2 {
            score += 18.0;
        }
        // prefer new bin when current item nearly fills its bin AND next item is large
        if item_size as f64 >= cap * 0.8 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        // new-bin lookahead: if best open-bin post-residual would be dead space, open fresh bin
        if r > 0 && r < next_item_size && r < 12 {
            score -= 20.0;
        }
    }

    score
}

