            if pr - nxt <= 8.0 {
                score -= 80.0;
            }
            if pr - nxt <= 3.0 {
                score -= 70.0;
            }
            // near-perfect handoff: leave at most a tiny sliver
            if pr - nxt <= 2.0 {
                score -= 25.0;
            }
