            score += (nxt - pr) * 5.0;
        } else if pr >= nxt && (r - next_item_size) % 10 == 0 {
            score -= 26.0;
        }
        if pr >= nxt && pr - nxt >= 20.0 {
            score -= 10.0;
        }
        // Penalize leaving a gap that is too large to be useful but not reusable.
        if pr > nxt && pr - nxt > 10.0 && pr - nxt < (nxt * 0.5).max(8.0) {
            score += 15.0;
        }
        if pr > 0.0 && pr < nxt * 0.35 {
            score += 7.0;
        }
        if pr > 0.0 && pr < nxt * 0.6 && pr >= nxt * 0.35 {
            score += 11.0;
        }
