        if !any_fits_next && next_item_size > 0 && open_bins_count > 0 {
            score -= 18.0;
        }
        // Dead-space guard: if mean open-bin residual would strand dead space
        // smaller than the next item, prefer a fresh bin.
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 24.0;
        }
        // Prefer new bin when current item nearly fills its bin AND next item is large.
        if item_size as f64 >= cap * 0.8 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        // New-bin lookahead: if the resulting post-residual is dead space, open fresh.
        if r > 0 && r < next_item_size && r < 12 {
            score -= 20.0;
        }
        // Late-stream consolidation: near the end, squeeze into existing bins.
        let remaining = total_items.saturating_sub(step_index);
        if remaining < 50 && open_bins_count > 0 {
            score += 35.0;
        }
    }

    score
}

