    if fill >= 0.92 {
        score -= 26.0;
    } else if fill >= 0.9 {
        score -= 21.0;
    } else if fill >= 0.7 {
        score -= 10.0;
    } else if fill < 0.28 {
        score += 9.0;
    }

    // Open-bin pressure
    score += 2.2 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Lookahead on next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = r as f64;
        if pr == nxt {
            score -= 390.0;
            if fitting_bins_count <= 3 {
                score -= 40.0;
            }
            if fill_ratio > 0.9 {
                score -= 25.0;
            }
        } else if pr >= nxt && pr - nxt <= 10.0 {
            score -= 145.0;
            if pr - nxt <= 8.0 {
                score -= 80.0;
            }
            if pr - nxt <= 3.0 {
                score -= 70.0;
            }
        } else if r > 0 && r < next_item_size {
            score += (nxt - pr) * 5.0;
        } else if pr >= nxt && (r - next_item_size) % 10 == 0 {
            score -= 26.0;
        }
        if pr >= nxt && pr - nxt >= 20.0 {
            score -= 10.0;
        }
        if pr > nxt && pr - nxt > 10.0 && pr - nxt < (nxt * 0.5).max(8.0) {
            score += 15.0;
        }
        if pr > 0.0 && pr < nxt * 0.35 {
            score += 7.0;
        }
        if pr > 0.0 && pr < nxt * 0.6 && pr >= nxt * 0.35 {
            score += 11.0;
        }
        // Two-item lookahead: residual can hold next item plus another small one
        if pr >= nxt && pr - nxt >= nxt && pr - nxt < 2.0 * nxt + 6.0 {
            score -= 22.0;
        }
        if pr > nxt * 1.5 && pr < nxt * 2.0 {
            score += 6.0;
        }
        if pr >= nxt && (pr - nxt) as u32 % next_item_size == 0 && pr - nxt > 0.0 {
            score -= 13.0;
        }
        // multiplicative chain: pr is k * next_item_size for small k
        if pr >= nxt && (pr as u32) % next_item_size == 0 {
            let k = (pr / nxt).round();
            if k >= 2.0 && k <= 4.0 {
                score -= 18.0 + 6.0 * (4.0 - k);
            }
        }
        // near-perfect two-step chain reward
        if pr >= nxt && (pr - nxt) as u32 <= 6 && fitting_bins_count >= 2 {
            score -= 18.0;
        }
        // penalize leaving residuals just barely above next_item_size
        if pr > nxt && pr - nxt <= 4.0 {
            score -= 9.0;
        }
        // near-fit residual: can't hold next item but is mostly filled by it
        if pr >= nxt * 0.7 && pr < nxt {
            score += 6.0;
        }
        // dead-space penalty: residual too small to ever be useful again
        if pr > 0.0 && pr < 8.0 && nxt > pr {
            score += 14.0 + 2.0 * (8.0 - pr);
        }
        // reward leaving exactly a small-item-friendly gap
        if pr >= nxt && pr - nxt <= 2.0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: prefer the only fitting open bin over a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }
    if fitting_bins_count <= 2 && r >= next_item_size && r > 0 {
        score -= 12.0;
    }

    // Mean-residual homing
    score += (mean_residual - bin_residual as f64) * 1.5;

    // Waste ratio penalty
    if item_size > 0 {
        let waste_ratio = r as f64 / (r + item_size) as f64;
        score += waste_ratio * 22.0;
    }

    // New empty bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_fill = 1.0 - mean_residual / cap;
        if avg_open_fill < 0.65 && progress > 0.08 {
            score += 55.0;
        } else {
            score += 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 55.0;
        }
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.6 {
            score -= 30.0;
        }
        if open_bins_count > 3 {
            score += 8.0;
        }
        if total_items.saturating_sub(step_index) > 200 && open_bins_count < 12 {
            score -= 12.0;
        }
        if (mean_residual - r as f64).abs() < 5.0 {
            score -= 10.0;
        }
        if next_item_size as f64 >= cap * 0.9 {
            score -= 15.0;
        }
        if next_item_size as f64 > mean_residual * 1.4 && total_items.saturating_sub(step_index) > 100 {
            score -= 9.0;
        }
        if next_item_size <= item_size && item_size as f64 >= cap * 0.5 {
            score -= 25.0;
        }
        if total_items.saturating_sub(step_index) < 50 && open_bins_count > 8 {
            score += 14.0;
        }
        // avoid opening a new bin when an open bin would end near-empty anyway
        if fitting_bins_count > 0 && next_item_size > 0 && item_size as f64 >= cap * 0.8 {
            score += 35.0;
        }
        // prefer new bin when current item nearly fills its bin AND next item is large
        if item_size as f64 >= cap * 0.8 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        // new-bin lookahead: if best open-bin post-residual would be dead space, open fresh bin
        if r > 0 && r < next_item_size && r < 12 {
            score -= 20.0;
        }
        // no open bin can hold the next item: keep a fresh bin ready
        let any_fits_next = fitting_bins_count > 0 && mean_residual >= next_item_size as f64;
        if !any_fits_next && next_item_size > 0 && open_bins_count > 0 {
            score -= 18.0;
        }
    }

    score
}

