    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as i32) as f64 * 12.0;
    }
    // Mid-range dead space (11..=20) is mildly penalized since typical items >= 10.
    if post_residual > 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
