    }

    // Compare residual against mean residual across open bins:
    // prefer using bins with less residual (more filled) when similar.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when open bins are poor fits.
        score += 150.0;
        // If no open bin fits (this is the only candidate), make new bin cheap.
        if fitting_bins_count == 0 {
