pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item would still fit in the post-residual, reward it;
    // if the next item is larger than post_residual but this is the only fitting bin,
    // soften the penalty (we had no choice).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing bins are fragmented or the item is large relative to mean space.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
        let item_heavy = item_size as f64 / bin_capacity as f64;
        // Penalize new bins mildly; reduce penalty under high fragmentation/pressure.
        score += 8.0 - 6.0 * (fragmentation / bin_capacity as f64) - 4.0 * pressure.min(1.0) - 5.0 * item_heavy;
    }

    // Global balance: prefer bins whose residual is near the mean (keeps bins homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: early in the stream, keep bins flexible (mild reward for larger post-residual);
    // late in the stream, allow aggressive packing (tight fits matter more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    // Reward closing bins exactly (perfect fill).
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

