pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on wasted space, weighted by stream progress
    let mut score = post * (1.0 + progress * norm_post);

    // Smooth coupling: post_residual vs mean residual deviation
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.5 + progress);

    // Reward tight fits via smooth saturating term
    let tight = 1.0 - norm_post;
    score -= 6.0 * tight * tight * (1.0 + progress);

    // Last-chance bonus (smooth in fitting_bins_count)
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 10.0 * scarcity * (1.0 - progress * 0.5);

    // Lookahead: penalize if next item cannot use post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if post >= nx { 1.0 } else { 0.0 };
        let gap = ((nx - post) as f64).abs() / cap;
        score += (1.0 - fits_next) * 5.0 * gap * (1.0 + progress);
        score -= fits_next * 3.0 * (1.0 - gap);
    }

    // Mild penalty for spreading across many bins late in stream
    score += 0.4 * open_bins_count as f64 * progress * norm_post;

    // New-bin candidate: smooth preference when residual is full and fits are scarce
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - scarcity) * (0.3 + 0.7 * progress) - 4.0 * scarcity;
    }

    score
}

