        } else if pr >= nxt && pr - nxt <= 10.0 {
            score -= 145.0;
            if pr - nxt <= 8.0 {
                score -= 80.0;
            }
            if pr - nxt <= 3.0 {
                score -= 70.0;
            }
        } else if r > 0 && r < next_item_size {
            score += (nxt - pr) * 5.0;
        } else if pr >= nxt && (r - next_item_size) % 10 == 0 {
            score -= 26.0;
        }
        if pr >= nxt && pr - nxt >= 20.0 {
            score -= 10.0;
        }
        if pr > nxt && pr - nxt > 10.0 && pr - nxt < (nxt * 0.5).max(8.0) {
            score += 15.0;
        }
        if pr > 0.0 && pr < nxt * 0.35 {
            score += 7.0;
        }
        if pr > 0.0 && pr < nxt * 0.6 && pr >= nxt * 0.35 {
            score += 11.0;
        }
        if pr >= nxt && (pr - nxt) as u32 % next_item_size == 0 && pr - nxt > 0.0 {
            score -= 13.0;
        }
        if pr >= nxt && pr - nxt >= nxt && pr - nxt < 2.0 * nxt + 6.0 {
            score -= 22.0;
        }
        if pr > nxt * 1.5 && pr < nxt * 2.0 {
            score += 6.0;
        }
        if nxt > 0.0 && pr >= nxt && (pr as u32) % next_item_size == 0 {
            let k = (pr as f64 / nxt).round();
            if k >= 2.0 && k <= 4.0 {
                score -= 18.0 + 6.0 * (4.0 - k);
            }
        }
        if pr > nxt && pr - nxt > 0.0 && pr - nxt < 10.0 {
            score -= 6.0;
        }
        // dead-space penalty: residual too small to ever be useful again
        if pr > 0.0 && pr < 8.0 && nxt > pr {
            score += 14.0 + 2.0 * (8.0 - pr);
        }
        // reward leaving exactly a small-item-friendly gap
        if pr >= nxt && pr - nxt <= 2.0 {
            score -= 25.0;
        }
        // penalize residuals that cannot fit next item but are large enough to be wasted
        if pr >= nxt * 0.7 && pr < nxt {
            score += 6.0;
        }
    }

    score += (mean_residual - bin_residual as f64) * 1.5;

    if item_size > 0 {
        let waste_ratio = r as f64 / (r + item_size) as f64;
        score += waste_ratio * 20.0;
    }

    score += 2.2 * open_bins_count as f64 * (1.0 - fill_ratio);

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if fitting_bins_count <= 2 && r >= next_item_size && r > 0 {
        score -= 12.0;
    }

    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_fill = 1.0 - mean_residual / cap;
        if avg_open_fill < 0.65 && progress > 0.08 {
            score += 55.0;
        } else {
            score += 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 55.0;
        }
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.6 {
            score -= 30.0;
        }
        if open_bins_count > 3 {
            score += 8.0;
        }
        if total_items.saturating_sub(step_index) > 200 && open_bins_count < 12 {
            score -= 12.0;
        }
        if (mean_residual - r as f64).abs() < 5.0 {
            score -= 10.0;
        }
        if next_item_size as f64 >= cap * 0.9 {
            score -= 15.0;
        }
        if next_item_size as f64 > mean_residual * 1.4 && total_items.saturating_sub(step_index) > 100 {
            score -= 9.0;
        }
        if next_item_size <= item_size && item_size as f64 >= cap * 0.5 {
            score -= 25.0;
        }
        let any_fits_next = fitting_bins_count > 0 && mean_residual >= next_item_size as f64;
        if !any_fits_next && next_item_size > 0 && open_bins_count > 0 {
            score -= 18.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 24.0;
        }
        // prefer new bin when current item nearly fills its bin AND next item is large
        if item_size as f64 >= cap * 0.8 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        // new-bin lookahead: if best open-bin post-residual would be dead space, open fresh bin
        if r > 0 && r < next_item_size && r < 12 {
            score -= 20.0;
        }
        // late-stream consolidation: squeeze into existing bins near the end
        let remaining = total_items.saturating_sub(step_index);
        if remaining < 50 && open_bins_count > 0 {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual in the lowest quarter of capacity
    // is "dead space" -> penalize strongly.
    let q = post_residual / (bin_capacity / 4); // 0..=4 harmonic class
    score += (q as f64) * (bin_capacity as f64) * 0.25;

    // Exact fit (post_residual == 0) is perfect: big reward.
    if post_residual == 0 {
        score -= bin_capacity as f64 * 2.0;
    } else {
        // Penalize residuals that are too small for the minimum item size (1..100
        // range, but historically small items exist) - dead space below 10.
        if post_residual < 10 {
            score += bin_capacity as f64 * 1.5;
        }
        // Penalize residuals that cannot fit the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Reward residuals that can fit the next item (keeps bin useful).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: only one bin fits -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= bin_capacity as f64 * 0.75;
    }

    // New-bin candidate: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins unless open bins are nearly full on average.
        score += bin_capacity as f64 * (0.5 + pressure);
        if open_bins_count == 0 {
            score -= bin_capacity as f64 * 2.0;
        }
    }

    // Progress-dependent tightness: later in the stream, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.1 * progress;

    // Harmonic modulo bonus: post_residual divisible by common item classes (5,10)
    // stays reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

