pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1) are
    // impossible, but small gaps that few future items can use are dead weight.
    // Penalize gaps that are too small to hold any plausible next item.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if next_item_size > 0 {
            if (next_item_size as f64) > gap {
                // Gap cannot fit the lookahead item: strong dead-space penalty,
                // scaled by how "wasted" the gap is relative to the item.
                score += 12.0 + gap * 0.35;
            } else {
                // Gap fits the lookahead item: reward tight follow-up fit.
                score -= 6.0 * (1.0 - gap / (next_item_size as f64 + 1.0));
            }
        } else {
            // Last item: leftover space is pure waste; minimize it hard.
            score += 8.0;
        }
    } else {
        // Perfect fill: heavily reward closing the bin completely.
        score -= 25.0;
    }

    // Reward tight fits generally: smaller post_residual relative to capacity.
    score -= 20.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.25 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins would
    // leave large dead space. An empty bin has huge residual; make it unattractive
    // unless the item is large and would leave a big gap elsewhere.
    if bin_residual == bin_capacity {
        // Baseline penalty for new bin; relax if open bins are already fragmented.
        score += 18.0 - 0.1 * (mean_residual.min(100.0));
        // If item is large (would leave small gap in a fresh bin), new bin is ok.
        score -= 0.15 * (item_size as f64);
        // Early in stream, opening bins is cheaper.
        score -= 10.0 * (1.0 - progress);
    }

    // Mean-residual coupling: if this bin's post-residual is far below the mean,
    // it's a good consolidation; if far above, it fragments the fleet.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.10 * (mean_residual - pr);
    } else {
        score += 0.15 * (pr - mean_residual);
    }

    score
}

