        if next_item_size <= item_size && item_size as f64 >= cap * 0.5 {
            score -= 25.0;
        }
        // If no open bin can hold the NEXT item either, opening a fresh
        // bin now is cheaper than stranding residual space.
        let any_fits_next = fitting_bins_count > 0 && mean_residual >= next_item_size as f64;
        if !any_fits_next && next_item_size > 0 && open_bins_count > 0 {
            score -= 18.0;
        }
        // Dead-space guard: if the best open-bin placement would strand a
        // residual smaller than the next item (unusable dead space), opening
        // a fresh bin preserves capacity for future large items.
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 24.0;
        }
        // Prefer new bin when current item nearly fills its bin AND next
        // item is large relative to the fleet's spare space.
        if item_size as f64 >= cap * 0.8 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        // New-bin lookahead: if the best open-bin post-residual would be
        // tiny dead space, open a fresh bin instead.
        if r > 0 && r < next_item_size && r < 12 {
            score -= 20.0;
        }
        // Late-stream consolidation: near the end, squeeze into existing bins.
        let remaining = total_items.saturating_sub(step_index);
        if remaining < 50 && open_bins_count > 0 {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, heavily favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 150.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize small unusable leftovers.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Penalize creating residual far below mean residual (fragmenting well-packed state),
    // but only if leftover is small and unusable.
    if post_residual > 0 {
        let small_gap = (mean_residual - post_residual as f64).max(0.0);
        score += 0.3 * small_gap;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: make empty bin attractive only when open bins would waste a lot.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) - 0.4 * mean_residual + 50.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0; // fresh bin can host a clean pair
