    }

    // Slight preference for tighter bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, be more willing to open new bins;
    // late in the stream, strongly prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let late_bias = 1.0 + 2.5 * progress;
    score *= late_bias;

    // Last-chance bin: strong reward, scaled by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 30.0 + 40.0 * tightness;
