    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here anyway; slight penalty for leaving mid-range gaps.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < 10.0 {
                score += 5.0; // dead space creation
            }
        }
    }

    // Prefer bins whose residual deviates from the mean (consolidate fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

