        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild reward for high fill ratio (small post-residual relative to capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    score
}

