pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into capacity-fraction bands
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Penalize dead space in awkward bands (post_residual in (0,10) is nearly unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Sweet spots: post_residual divisible structure (exact quarters of capacity)
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if post_residual % 25 == 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Harmonic coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward if next item exactly or nearly fills the remainder
            let gap = post_residual - next_item_size;
            if gap == 0 { score -= 20.0; }
            else if gap < 10 { score -= 10.0; }
            else { score -= 5.0 * (1.0 - gap as f64 / cap); }
        } else {
            // next item cannot use this remainder: penalize large wasted remainders
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make empty bins attractive only when item is large
    // and open bins have poor fit (post_residual small relative to item)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // large items (>50% cap) prefer fresh bins; small items prefer existing bins
        let large_bias = if item_size > bin_capacity / 2 { -8.0 } else { 15.0 };
        score += large_bias + 10.0 * (1.0 - progress) - 0.3 * open_bins_count as f64;
    }

    // Mild preference for bins below mean residual (keeps tight bins tight)
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let r = post_residual;

    // Fill ratio of this placement: strongly reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.95 {
