    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.5);
        if item_size >= 50 && fitting_bins_count == 0 {
            score -= 20.0; // large item, no alternatives: open a fresh bin
        } else if tightness < 0.6 {
            score += 10.0 + pressure; // discourage needless new bins
        } else {
            score += 3.0;
        }
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 10.0; // next item stranded by this placement
    }

    // Early stream: be slightly more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.3 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let r = post_residual;

    // Fill ratio of this placement: strongly reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.95 {
        score -= 22.0;
    } else if fill_ratio > 0.85 {
        score -= 9.0;
    } else if fill_ratio > 0.75 {
        score -= 3.0;
    }

    if r == 0 {
        score -= 950.0; // perfect fit
    } else if r < 10 {
        score += 70.0; // dead space below min item
        // tiny stranded slivers are pure waste — extra penalty
        score += 2.0 * (10 - r) as f64;
    } else {
        if r % 10 == 0 {
            score -= 15.0;
        } else if r % 25 == 0 {
            score -= 11.0;
        } else if r % 5 == 0 {
            score -= 4.0;
        } else {
            score += 10.0;
        }
        // Mid-range residuals are highly usable by typical item sizes.
        if r >= 15 && r <= 45 {
            score -= 7.0;
        }
        // Penalize residuals too small for the upcoming item.
        if r < next_item_size {
            score += (next_item_size - r) as f64 * 3.0;
        }
    }

    // Fill-level coupling: reward near-closed bins.
    let fill = (bin_residual as f64) / cap;
    if fill >= 0.92 {
        score -= 28.0;
    } else if fill >= 0.9 {
        score -= 21.0;
    } else if fill >= 0.7 {
        score -= 9.0;
    } else if fill < 0.28 {
        score += 9.0;
    }

    // Lookahead couplings with graded rewards.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = r as f64;
        if pr == nxt {
            score -= 390.0;
            if fitting_bins_count <= 3 {
                score -= 40.0;
            }
        } else if pr >= nxt && pr - nxt <= 10.0 {
            score -= 145.0;
            if pr - nxt <= 8.0 {
                score -= 80.0;
            }
            if pr - nxt <= 3.0 {
                score -= 70.0;
            }
        } else if r > 0 && r < next_item_size {
            score += (nxt - pr) * 5.0;
        } else if pr >= nxt && (r - next_item_size) % 10 == 0 {
            score -= 26.0;
        }
        if pr >= nxt && pr - nxt >= 20.0 {
            score -= 10.0;
        }
        // Penalize leaving a gap that is too large to be useful but not reusable.
        if pr > nxt && pr - nxt > 10.0 && pr - nxt < (nxt * 0.5).max(8.0) {
            score += 15.0;
        }
        if pr > 0.0 && pr < nxt * 0.35 {
            score += 7.0;
        }
        if pr > 0.0 && pr < nxt * 0.6 && pr >= nxt * 0.35 {
            score += 11.0;
        }
        // Two-item lookahead: residual that fits exactly two of the next item.
        if pr >= nxt && (pr - nxt) as u32 % next_item_size == 0 && pr - nxt > 0.0 {
            score -= 13.0;
        }
        // Residual can hold next item plus a small remainder usable later.
        if pr >= nxt && pr - nxt >= nxt && pr - nxt < 2.0 * nxt + 6.0 {
            score -= 22.0;
        }
        if pr > nxt * 1.5 && pr < nxt * 2.0 {
            score += 6.0;
        }
        // Exact k-multiple fit of the residual by the next item is a
        // near-perfect closure — reward proportionally to k.
        if nxt > 0.0 && pr >= nxt && (pr as u32) % next_item_size == 0 {
            let k = (pr as f64 / nxt).round();
            if k >= 2.0 && k <= 4.0 {
                score -= 18.0 + 6.0 * (4.0 - k);
            }
        }
        // Penalize residuals that are awkwardly just above the next item
        // but leave a dead sliver (< 10) after consuming it.
        if pr > nxt && pr - nxt > 0.0 && pr - nxt < 10.0 {
            score -= 6.0;
        }
        // Dead-space avoidance — residual in (0, next) that can never be
        // filled is pure waste; scale penalty by closeness to zero.
        if pr > 0.0 && pr < nxt {
            score += (nxt - pr) * 2.0;
            if pr < 8.0 {
                score += 14.0 + 2.0 * (8.0 - pr);
            }
        }
        // Reward placements that leave exactly a small-item-friendly gap.
        if pr >= nxt && pr - nxt <= 2.0 {
            score -= 25.0;
        }
        // Penalize residuals that cannot fit next item but are large enough
        // to be wasted capacity.
        if pr >= nxt * 0.7 && pr < nxt {
            score += 6.0;
        }
        // Reward leaving a "friendly" size (multiple of 5) in the mid band.
        if pr >= 10.0 && pr <= 60.0 && r % 5 == 0 {
            score -= 5.0;
        }
    }

    // Deviation from fleet mean: prefer bins that consolidate spare space.
    score += (mean_residual - bin_residual as f64) * 1.5;

    // Waste ratio of this placement.
    if item_size > 0 {
        let waste_ratio = r as f64 / (r + item_size) as f64;
        score += waste_ratio * 20.0;
    }

    // Fragmentation pressure: reward filling bins with many open bins competing.
    score += 2.2 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance / scarce-bin pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if fitting_bins_count <= 2 && r >= next_item_size && r > 0 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening unless bins are nearly full or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_fill = 1.0 - mean_residual / cap;
        if avg_open_fill < 0.65 && progress > 0.08 {
            score += 55.0;
        } else {
            score += 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 55.0;
        }
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.6 {
            score -= 30.0;
        }
        if open_bins_count > 3 {
            score += 8.0;
        }
        if total_items.saturating_sub(step_index) > 200 && open_bins_count < 12 {
            score -= 12.0;
        }
        if (mean_residual - r as f64).abs() < 5.0 {
            score -= 10.0;
        }
        if next_item_size as f64 >= cap * 0.9 {
            score -= 15.0;
        }
        if next_item_size as f64 > mean_residual * 1.4 && total_items.saturating_sub(step_index) > 100 {
            score -= 9.0;
        }
        if next_item_size <= item_size && item_size as f64 >= cap * 0.5 {
            score -= 25.0;
        }
        // If no open bin can hold the NEXT item either, opening a fresh
        // bin now is cheaper than stranding residual space.
        let any_fits_next = fitting_bins_count > 0 && mean_residual >= next_item_size as f64;
        if !any_fits_next && next_item_size > 0 && open_bins_count > 0 {
            score -= 18.0;
        }
        // Dead-space guard — if the best open-bin placement would strand a
        // residual smaller than the next item, opening a fresh bin preserves
        // that capacity for future large items.
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 24.0;
        }
        // New-bin lookahead: if open-bin post-residual would be tiny dead
        // space, a fresh bin is better.
        if r > 0 && r < next_item_size && r < 12 {
            score -= 20.0;
        }
        // Prefer new bin when current item nearly fills its bin and next
        // item is larger than typical open residual.
        if item_size as f64 >= cap * 0.8 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        // Late-stream consolidation — near the end, squeeze into existing bins.
        let remaining = total_items.saturating_sub(step_index);
        if remaining < 50 && open_bins_count > 0 {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item can't fit here; penalize dead space relative to next item
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Reward matching against mean residual: bins with residual close to mean are "normal" slots
    let mean_gap = ((bin_residual as f64) - mean_residual).abs();
    score += 0.05 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize creating tiny unusable residuals (dead space < typical min item ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer keeping a fresh empty bin as a reserve unless this is a poor fit elsewhere
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost of opening a new bin,
        // discounted when current best placement would waste space
        score += 15.0 + 0.5 * (open_bins_count as f64);
        if post_residual as f64 > mean_residual {
            score -= 10.0; // placing here wastes more than average — new bin more attractive
        }
    }

    // Slight preference for consolidating into fewer bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - tightness);

    score
}

