pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Perfect fit: eliminate dead space entirely
    if post_residual == 0 {
        score -= 12.0;
    }

    // Penalize residual too small for the lookahead item (unusable dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * post_residual as f64 * (1.0 + 0.5 * progress);
    }

    // Reward residuals that can still accommodate the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.25 * next_item_size as f64 * (1.0 - 0.4 * progress);
    }

    // Last-chance bin: strongly favor the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: mild penalty so open bins are preferred, decaying
    // as the stream progresses (less future to amortize fragmentation over)
    if bin_residual == bin_capacity {
        score += 7.0 + 0.15 * open_bins_count as f64 - 3.0 * progress;
    }

    // Reward using large items in tighter bins (efficiency of packing)
    score -= 0.05 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Slight penalty for deviating from the fleet's mean residual,
    // encouraging balanced residual distribution
    score += 0.03 * (mean_residual - post_residual as f64).abs();

    // Early stream: prefer consolidating into fewer bins
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    score
}

