        }
        // When many bins remain open with slack, discourage opening.
        if open_bins_count > 6 && mean_residual > next_item_size as f64 * 1.5 {
            score += 18.0;
        }
        // NEW: opening a fresh bin is attractive when the fresh-bin residual
        // (cap - item) is a multiple of 5 and thus reusable by future items.
        if item_size as f64 >= cap * 0.5 && (bin_capacity - item_size) % 5 == 0 {
            score -= 8.0;
        }
        // NEW: discourage opening when remaining stream is short and some
        // open bin still has substantial slack.
        if remaining < 120 && mean_residual >= item_size as f64 * 1.2 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot fraction" of capacity remains
    let pr = post_residual;
    let class = pr / 10; // integer division -> decile classes 0..10
    match class {
        0 => score -= 12.0,             // nearly perfect fill: golden
        1 => score -= 7.0,              // excellent
        2 => score -= 4.0,
        3 => score -= 2.0,
        4 => score -= 0.5,
        5 => score += 1.0,              // half-empty: mediocre
        6 => score += 2.5,
        7 => score += 4.5,
        8 => score += 7.0,
        9 => score += 9.0,              // mostly empty: wasteful placement
        _ => {}                          // class 10 = brand-new bin, handled below
    }

    // Modulo-4 harmonic bonus: residuals divisible by 4/5 pair well with common item sizes
    if pr % 4 == 0 { score -= 1.5; }
    if pr % 5 == 0 { score -= 1.0; }
    if pr % 10 == 0 && pr > 0 { score -= 1.0; }

    // Penalize dead space that no plausible item (1..100) can use well:
    // tiny residuals (1..9) are almost unusable -> harsh penalty
    if pr > 0 && pr < 10 {
        score += 6.0 - pr as f64 * 0.4;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0;
        } else if next_item_size <= pr {
            let npr = pr - next_item_size;
            score -= 4.0 - (npr as f64) * 0.05;
            if npr < 10 { score += 2.0; } // leaves another dead sliver
        } else {
            // next item won't fit here anyway; slightly reward leaving large residual
            score += 1.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral baseline, but avoid opening new bins
    // when good fitting bins exist; encourage when residuals are fragmented.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: its residual is cap (already in score).
        score += 3.0; // default mild penalty: prefer reusing open bins
        if fitting_bins_count == 0 { score -= 20.0; } // no alternative: must open
        if next_item_size > 0 && next_item_size >= 50 && mean_residual < 15.0 {
            score -= 6.0; // big item coming, open bins too full -> fresh bin good
        }
        if open_bins_count > 6 && mean_residual < 12.0 {
            score -= 4.0; // fragmented state, consolidation via new bin
        }
    }

    // Mild stream-aware tightening: early on, be slightly greedy about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual <= 15 && post_residual > 0 {
        score -= 2.0 * (1.0 - progress);
    }

    // Slight preference to balance residuals toward mean (avoid extreme skew)
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: small nonzero gaps are unusable for
    // typical items (sizes >= 1 but practically >= 10); penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Medium gaps (10..20) are only mildly useful; slight penalty gradient.
    if post_residual >= 10 && post_residual < 20 {
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (which also carries the new-bin residual cost).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into
    // existing bins; a new bin candidate (residual == capacity) is penalized
    // proportionally to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * open_bins_count as f64;
    } else {
        // Reward filling existing bins more when many bins are open.
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit in post residual but would fit elsewhere,
    // mildly penalize leaving a gap the next item can't use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Late in the stream, tighten up: waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter post-fit residual is better (already the base).

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post residual (perfect chain), or at least fits well.
    if next_item_size > 0 {
        if post_residual as u64 == next_item_size as u64 {
            score -= 60.0; // perfect 2-step chain: residual consumed exactly
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.5 * slack; // next item fits, reward tight follow-ups
        } else {
            // next item won't fit here; residual becomes dead space risk
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Penalize residuals that are too small to ever be useful
    // (min item size 1, but typical items are larger).
    if post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: bins already fragmented relative to
    // the fleet average are less attractive targets.
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and the current stream is early (room to build good bins).
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin: mild penalty so we prefer reusing open bins,
        // but strong bonus when no existing bin can host the item.
        score += 3.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // If the lookahead item would fit exactly in the fresh residual,
        // a new bin pairs nicely with the next item.
        if next_item_size > 0 && (next_item_size as u32) == post_residual {
            score -= 4.0;
        }
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score += 2.0;
        }
        // Late in the stream, avoid proliferating bins with large leftovers.
        score += 0.02 * post_residual as f64 * progress;
    } else {
        // Reward tight fits: lower score when the bin becomes nearly full.
        score -= (bin_capacity - post_residual) as f64 * 0.05;

        // Last-chance bin: strongly prefer using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 6.0;
        }

        // Perfect pairing: next item exactly fills the post residual.
        if next_item_size > 0 && (next_item_size as u32) == post_residual {
            score -= 5.0;
        }
        // Next item won't fit here: slight penalty for leaving awkward space.
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score += 1.0 + 0.02 * post_residual as f64;
        }

        // Prefer bins that are below the mean residual (i.e., already loaded),
        // consolidating items into fewer bins.
        score += 0.01 * (mean_residual - post_residual as f64);

        // With many open bins, discourage leaving mid-sized dead space.
        if open_bins_count > 4 {
            score += 0.03 * post_residual as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: minimize post residual, with non-linear shaping (quadratic + cubic).
    let mut score = post_norm * 100.0
        - 30.0 * post_norm * (1.0 - post_norm)
        + 20.0 * post_norm * post_norm * (1.0 - post_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late, dead space is penalized super-linearly.
    let coupling = post_norm * post_norm * (1.0 + 3.0 * progress) + 2.0 * progress * post_norm * (1.0 - post_norm);
    score += 40.0 * coupling;

    // Reward tight fits: item fills a large fraction of residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill * fill * (1.0 + progress);

    // Lookahead synergy: reward if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let nxt_fit = nxt / post.max(1.0);
            score -= 25.0 * nxt_fit * (1.0 - nxt_fit) * (1.0 + progress);
        } else {
            // penalize leaving residual that next item cannot use, scaled by progress
            score += 10.0 * progress * (1.0 - post_norm);
        }
    }

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - post_norm) * (1.0 + progress);
    }

    // Discard fragmentation relative to mean residual of open bins.
    score += 0.05 * (post - mean_residual).abs() * (1.0 + progress);

    // New empty bin candidate: penalize mildly early, more as stream progresses,
    // but relax the penalty when post residual would be very large (good for future items).
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - post_norm) * (0.5 + progress);
        score -= 10.0 * post_norm;
    }

    // Small global drift to prefer consolidating bins early.
    score += 0.01 * open_bins_count as f64 * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class: which quarter-band does post_residual fall into?
    let quarter = bin_capacity / 4; // 25
    let post_class = post_residual / quarter; // 0..4
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / quarter };

    // Reward when post_residual's harmonic class matches next item's class band
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - gap / cap);
        // exact modulo match: post_residual % quarter aligns with next item band
        if post_class == next_class {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here regardless; penalize dead space
        score += 3.0;
    }

    // Integer-division thresholds on post_residual: dead-space zones
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    } else if post_residual < quarter {
        score += 4.0;  // small dead zone
    } else if post_residual == quarter {
        score -= 2.0;  // exact harmonic alignment
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize unless current bin would leave bad residue
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count == 0 { score -= 20.0; }
    }

    // Tight fit reward
    if post_residual == 0 {
        score -= 15.0;
    }

    // Fraction of capacity used by this placement
    let fill = item_size as f64 / cap;
    score -= 5.0 * fill;

    // Stream phase modulation: prefer consolidation early, hoarding late
    let phase = step_index as f64 / total_items.max(1) as f64;
    score += phase * (open_bins_count as f64) * 0.5;

    // Mean-residual coupling: discourage bins far below mean residual (fragmenting)
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept another item (sizes >= 1, but realistically >= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0; // very unlikely to be useful
    } else if post_residual < 35 {
        score += 8.0;  // marginal gap
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual
    // would create heavy dead space. Empty bin has large residual by default,
    // so add open-bin pressure to keep it from winning trivially.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    }

    // Pressure term: when many bins are open, prefer filling existing bins
    // (higher score for bins with large residual relative to mean).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_pressure = 0.15 * open_bins_count as f64 * (1.0 + progress);
    score += open_pressure * (bin_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // reward leaving that gap; if next item is larger than post_residual,
    // the gap becomes dead space for the near future -> penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 12.0;
        }
    }

    // Slight preference for bins already below mean residual (tighter bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
