        if pr >= nxt && pr - nxt >= nxt && pr - nxt < 2.0 * nxt + 6.0 {
            score -= 22.0;
        }
        if pr > nxt * 1.5 && pr < nxt * 2.0 {
            score += 6.0;
        }
        if nxt > 0.0 && pr >= nxt && (pr as u32) % next_item_size == 0 {
            let k = (pr as f64 / nxt).round();
            if k >= 2.0 && k <= 4.0 {
                score -= 18.0 + 6.0 * (4.0 - k);
            }
        }
        if pr > nxt && pr - nxt > 0.0 && pr - nxt < 10.0 {
            score -= 6.0;
        }
        if pr > 0.0 && pr < 8.0 && nxt > pr {
            score += 14.0 + 2.0 * (8.0 - pr);
        }
        if pr >= nxt && pr - nxt <= 2.0 {
            score -= 25.0;
        }
        if pr >= nxt * 0.7 && pr < nxt {
            score += 6.0;
        }
        if pr > 0.0 && pr < nxt {
            score += (mean_residual - pr) * 0.8;
        }
        if pr >= nxt && (pr as f64 - mean_residual).abs() <= 3.0 {
            score -= 9.0;
        }
        // NEW: exact two-next-item residual closure is very strong.
        if nxt > 0.0 && (pr - 2.0 * nxt).abs() <= 1.0 {
            score -= 55.0;
        }
        // NEW: residual that fits next item AND leaves a multiple of 5
        // is a reusable chain; reward graded by closeness to exact 5s.
        if pr >= nxt && (r - next_item_size) % 5 == 0 && pr - nxt >= 5.0 {
            score -= 8.0;
        }
    }

    score += (mean_residual - bin_residual as f64) * 1.5;

    if item_size > 0 {
        let waste_ratio = r as f64 / (r + item_size) as f64;
        score += waste_ratio * 20.0;
    }

    score += 2.2 * open_bins_count as f64 * (1.0 - fill_ratio);

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if fitting_bins_count <= 2 && r >= next_item_size && r > 0 {
        score -= 12.0;
    }

    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_fill = 1.0 - mean_residual / cap;
        if avg_open_fill < 0.65 && progress > 0.08 {
            score += 55.0;
        } else {
            score += 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 55.0;
        }
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.6 {
            score -= 30.0;
        }
        if open_bins_count > 3 {
            score += 8.0;
        }
        if total_items.saturating_sub(step_index) > 200 && open_bins_count < 12 {
            score -= 12.0;
        }
        if (mean_residual - r as f64).abs() < 5.0 {
            score -= 10.0;
        }
        if next_item_size as f64 >= cap * 0.9 {
            score -= 15.0;
        }
        if next_item_size as f64 > mean_residual * 1.4 && total_items.saturating_sub(step_index) > 100 {
            score -= 9.0;
        }
        if next_item_size <= item_size && item_size as f64 >= cap * 0.5 {
            score -= 25.0;
        }
        let any_fits_next = fitting_bins_count > 0 && mean_residual >= next_item_size as f64;
        if !any_fits_next && next_item_size > 0 && open_bins_count > 0 {
            score -= 18.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 24.0;
        }
        let remaining = total_items.saturating_sub(step_index);
        if remaining < 50 && open_bins_count > 0 {
            score += 35.0;
        }
        if item_size as f64 >= cap * 0.8 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        if r > 0 && r < next_item_size && r < 12 {
            score -= 20.0;
        }
        if item_size as f64 >= cap * 0.85 {
            score -= 12.0;
        }
        if open_bins_count > 6 && mean_residual > next_item_size as f64 * 1.5 {
            score += 18.0;
        }
        // NEW: opening a bin whose residual would exactly fit the next
        // item is a strong setup — reward it.
        if next_item_size > 0 && (cap - item_size as f64 - next_item_size as f64).abs() <= 2.0 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never be filled by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits into post_residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 10.0 * next_fit;
        if post_residual == next_item_size {
            score -= 15.0; // perfect two-item fill
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty for wasting capacity.
        score += 3.0 * (next_item_size as f64) / 100.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Cost of opening a new bin; reduce when open bins are fragmented
        // (mean residual low means poor reuse prospects).
        let fragmentation = 1.0 - (mean_residual / (bin_capacity as f64)).min(1.0);
        score += 20.0 - 25.0 * fragmentation;
        // Early in stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If item is large, new bin keeps big space for future items.
        score -= (item_size as f64) * 0.1;
    } else {
        // Prefer filling existing bins slightly over new ones.
        score -= 2.0;
        // Favor bins whose residual deviates from mean (specialization).
        let dev = ((bin_residual as f64) - mean_residual).abs();
        score -= 0.05 * dev;
    }

    // Time horizon: late in stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste (post residual), non-linearly weighted by stream progress.
    // Early: mild waste penalty; Late: strong waste penalty (dead space costly).
    let waste_weight = 1.0 + 3.0 * progress * progress;
    let mut score = waste_weight * (post * post) / cap;

    // Reward tight fits (small post_residual relative to item) via smooth coupling.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fit_ratio * fit_ratio * cap * (1.0 - progress);

    // Lookahead coupling: bonus if next item fits the post residual (smooth term).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        let compat = 1.0 - (gap / cap).abs().min(1.0);
        score -= 4.0 * compat * compat * (1.0 + progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    } else {
        // Slight penalty when many bins fit (prefer scarcity-driven placement).
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // Penalize bins far from mean residual (prefer balanced residual profile).
    score += 0.5 * ((post - mean_residual) / cap).powi(2) * cap;

    // Mild preference for consolidating into fewer bins when many are open.
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when item fits poorly
    // anywhere (large post residual in an existing bin) — smooth gate on waste.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 15.0 - 10.0 * (post / cap) * (post / cap);
        score -= 5.0 * progress;
    }

    score
}

