pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strongly reward zero post residual.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Harmonic class logic: post_residuals that are clean multiples of 20
    // (capacity / 5) partition well for future items; odd leftovers are worse.
    let class = post_residual % 20;
    match class {
        0 => score -= 3.0,
        1..=9 => score += 1.5,          // narrow slivers, likely dead space
        10 => score -= 1.0,             // half-slot, still reusable
        _ => {}                          // 11..19 neutral-ish
    }

    // Dead-space penalty: if the lookahead item cannot fit here,
    // penalize proportionally to the wasted gap.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    } else if next_item_size > 0 {
        // Reward chains: next item fits into the leftover space.
        score -= 2.0 + (post_residual - next_item_size) as f64 * 0.02;
    }

    // Last-chance bin: if this is the only bin that can take the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // When many bins compete, prefer the tightest fill (small post residual
    // already dominates, but add a mild tie-breaker on fill ratio).
    if fitting_bins_count > 2 {
        score -= (bin_residual - post_residual) as f64 * 0.05;
    }

    // Brand-new empty bin candidate: apply an opening penalty so it is only
    // chosen when no open bin offers a decent fit. The penalty decays slightly
    // with the number of already-open bins (encourages consolidation early).
    if bin_residual == bin_capacity {
        score += 20.0 + 0.15 * open_bins_count as f64;
    }

    // Stream progression: late in the stream, push toward consolidation by
    // mildly penalizing bins whose residual is far above the mean residual.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.05 * (post_residual as f64 - mean_residual).max(0.0);

    // Very large items (harmonic top class > 3/4 capacity): if this bin barely
    // accommodates the item, prefer it to avoid splitting large-item space.
    if item_size >= 75 && post_residual <= 25 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
