pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable tiny gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (near-perfect packing).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose residual is below average
    // (consume the fuller bins first to consolidate dead space).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 10 {
            score -= 20.0; // perfect chain fit
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use leftover: leftover is likely dead space.
        score += 8.0 * (post_residual as f64 / 100.0);
    }

    // New-bin candidate: opening a fresh bin is only attractive when item is
    // large and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || fill_ratio > 0.6 {
            score -= 10.0;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact lookahead match: post_residual equals next item size -> perfect packing.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small leftover.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 200.0 - leftover * 4.0;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving dead space, scaled by how dead it is.
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += (next_item_size as f64 - dead) * 6.0;
        }
    }

    // Penalize small unusable residuals (dead space) non-linearly.
    if post_residual < 10 {
        score += 150.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits relative to mean residual.
    score -= (bin_residual as f64 - post_residual as f64) * 0.5;
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent existing bins exist,
    // unless the stream is early and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 - 40.0 * progress;
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let r = post_residual;

    // Fill ratio of this placement: strongly reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.95 {
        score -= 22.0;
    } else if fill_ratio > 0.85 {
        score -= 9.0;
    } else if fill_ratio > 0.75 {
        score -= 3.0;
    }

    if r == 0 {
        score -= 950.0; // perfect fit
    } else if r < 10 {
        score += 70.0; // dead space below min item
    } else {
        if r % 10 == 0 {
            score -= 15.0;
        } else if r % 25 == 0 {
            score -= 11.0;
        } else if r % 5 == 0 {
            score -= 4.0;
        } else {
            score += 10.0;
        }
        // Mid-range residuals are highly usable by typical item sizes.
        if r >= 15 && r <= 45 {
            score -= 7.0;
        }
        // Penalize residuals too small for the upcoming item.
        if r < next_item_size {
            score += (next_item_size - r) as f64 * 3.0;
        }
    }

    // Fill-level coupling: reward near-closed bins.
    let fill = (bin_residual as f64) / cap;
    if fill >= 0.92 {
        score -= 28.0;
    } else if fill >= 0.9 {
        score -= 21.0;
    } else if fill >= 0.7 {
        score -= 9.0;
    } else if fill < 0.28 {
        score += 9.0;
    }

    // Lookahead couplings with graded rewards.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = r as f64;
        if pr == nxt {
            score -= 390.0;
            if fitting_bins_count <= 3 {
                score -= 40.0;
            }
        } else if pr >= nxt && pr - nxt <= 10.0 {
            score -= 145.0;
            if pr - nxt <= 8.0 {
                score -= 80.0;
            }
            if pr - nxt <= 3.0 {
                score -= 70.0;
            }
        } else if r > 0 && r < next_item_size {
            score += (nxt - pr) * 5.0;
        } else if pr >= nxt && (r - next_item_size) % 10 == 0 {
            score -= 26.0;
        }
        if pr >= nxt && pr - nxt >= 20.0 {
            score -= 10.0;
        }
        // Penalize leaving a gap that is too large to be useful but not reusable.
        if pr > nxt && pr - nxt > 10.0 && pr - nxt < (nxt * 0.5).max(8.0) {
            score += 15.0;
        }
        if pr > 0.0 && pr < nxt * 0.35 {
            score += 7.0;
        }
        if pr > 0.0 && pr < nxt * 0.6 && pr >= nxt * 0.35 {
            score += 11.0;
        }
        // Two-item lookahead: residual that fits exactly two of the next item.
        if pr >= nxt && (pr - nxt) as u32 % next_item_size == 0 && pr - nxt > 0.0 {
            score -= 13.0;
        }
        // Residual can hold next item plus a small remainder usable later.
        if pr >= nxt && pr - nxt >= nxt && pr - nxt < 2.0 * nxt + 6.0 {
            score -= 22.0;
        }
        if pr > nxt * 1.5 && pr < nxt * 2.0 {
            score += 6.0;
        }
        // Exact k-multiple fit of the residual by the next item is a
        // near-perfect closure — reward proportionally to k.
        if nxt > 0.0 && pr >= nxt && (pr as u32) % next_item_size == 0 {
            let k = (pr as f64 / nxt).round();
            if k >= 2.0 && k <= 4.0 {
                score -= 18.0 + 6.0 * (4.0 - k);
            }
        }
        // Penalize residuals that are awkwardly just above the next item
        // but leave a dead sliver (< 10) after consuming it.
        if pr > nxt && pr - nxt > 0.0 && pr - nxt < 10.0 {
            score -= 6.0;
        }
        // Dead-space avoidance: residual in (0, next) that cannot ever be
        // filled is pure waste; scale penalty by closeness to zero.
        if pr > 0.0 && pr < nxt {
            score += (nxt - pr) * 2.0;
        }
        // Reward placements that leave a "friendly" size (multiple of 5)
        // within the mid-range band, since such residuals get reused.
        if pr >= 10.0 && pr <= 60.0 && (r % 5 == 0) {
            score -= 5.0;
        }
        // Tiny leftover gap after next item is near-perfect.
        if pr >= nxt && pr - nxt <= 2.0 {
            score -= 25.0;
        }
        // Residual just below next item that will strand.
        if pr >= nxt * 0.7 && pr < nxt {
            score += 6.0;
        }
        // Dead-space penalty for residual too small to ever be useful again.
        if pr > 0.0 && pr < 8.0 && nxt > pr {
            score += 14.0 + 2.0 * (8.0 - pr);
        }
        // Combined dead-space metric — penalize placements whose
        // post-residual is a stranded fraction of capacity while other
        // bins could absorb the item with less waste.
        if pr > 0.0 && pr < nxt {
            score += (mean_residual - pr) * 0.8;
        }
        // Reward leaving residual that exactly matches the fleet-mean
        // usable gap, consolidating spare space across bins.
        if pr >= nxt && (pr as f64 - mean_residual).abs() <= 3.0 {
            score -= 9.0;
        }
        // NEW: dead-space ratio penalty — placements that strand a large
        // fraction of the consumed residual are worse than they look.
        if pr > 0.0 && pr < nxt {
            score += (nxt - pr) / nxt * 12.0;
        }
        // NEW: reward exact halving of residual by the next item (two
        // future fits possible without slivers).
        if pr >= nxt && (r == 2 * next_item_size || r == 3 * next_item_size) {
            score -= 30.0;
        }
    }

    // Deviation from fleet mean: prefer bins that consolidate spare space.
    score += (mean_residual - bin_residual as f64) * 1.5;

    // Waste ratio of this placement.
    if item_size > 0 {
        let waste_ratio = r as f64 / (r + item_size) as f64;
        score += waste_ratio * 20.0;
    }

    // Fragmentation pressure: reward filling bins with many open bins competing.
    score += 2.2 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance / scarce-bin pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if fitting_bins_count <= 2 && r >= next_item_size && r > 0 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening unless bins are nearly full or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_fill = 1.0 - mean_residual / cap;
        if avg_open_fill < 0.65 && progress > 0.08 {
            score += 55.0;
        } else {
            score += 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 55.0;
        }
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.6 {
            score -= 30.0;
        }
        if open_bins_count > 3 {
            score += 8.0;
        }
        if total_items.saturating_sub(step_index) > 200 && open_bins_count < 12 {
            score -= 12.0;
        }
        if (mean_residual - r as f64).abs() < 5.0 {
            score -= 10.0;
        }
        if next_item_size as f64 >= cap * 0.9 {
            score -= 15.0;
        }
        if next_item_size as f64 > mean_residual * 1.4 && total_items.saturating_sub(step_index) > 100 {
            score -= 9.0;
        }
        if next_item_size <= item_size && item_size as f64 >= cap * 0.5 {
            score -= 25.0;
        }
        // If no open bin can hold the NEXT item either, opening a fresh
        // bin now is cheaper than stranding residual space.
        let any_fits_next = fitting_bins_count > 0 && mean_residual >= next_item_size as f64;
        if !any_fits_next && next_item_size > 0 && open_bins_count > 0 {
            score -= 18.0;
        }
        // Dead-space guard: if the best open-bin placement would strand a
        // residual smaller than the next item, opening a fresh bin
        // preserves that capacity for future large items.
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 24.0;
        }
        // Late-stream consolidation: near the end, squeeze into existing bins.
        let remaining = total_items.saturating_sub(step_index);
        if remaining < 50 && open_bins_count > 0 {
            score += 35.0;
        }
        // Prefer new bin when current item nearly fills its bin AND next item is large.
        if item_size as f64 >= cap * 0.8 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        // New-bin lookahead: if best open-bin post-residual would be dead space, open a fresh bin.
        if r > 0 && r < next_item_size && r < 12 {
            score -= 20.0;
        }
        // Mid-stream: if the item nearly fills a fresh bin exactly
        // (post-residual of a new bin is small), opening is cheap and tight.
        if item_size as f64 >= cap * 0.85 {
            score -= 12.0;
        }
        // When many bins remain open with slack, discourage opening.
        if open_bins_count > 6 && mean_residual > next_item_size as f64 * 1.5 {
            score += 18.0;
        }
        // NEW: opening a fresh bin is attractive when the current item is
        // large enough that any open-bin fit leaves more dead space than
        // the new-bin post-residual would.
        if fitting_bins_count > 0 && (item_size as f64) > mean_residual * 0.8 && item_size < next_item_size * 2 {
            score += 14.0;
        }
        // NEW: early stream with few bins — open freely to build a good
        // residual landscape for later consolidation.
        if progress < 0.05 && open_bins_count < 4 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = post / cap;                       // fraction of capacity wasted after placement
    let mut score = fit * 100.0;

    // Reward tight fits (small post_residual)
    score -= (1.0 - fit).powf(3.0) * 40.0;

    // Penalize dead space that cannot be used by the next item
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += post * 0.6;                // unusable sliver
        } else {
            score -= post * 0.15;               // usable leftover
        }
        // Bonus if post_residual exactly accommodates next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // More competing bins -> mild penalty for wasting space in a scarce-fit situation
    if fitting_bins_count > 1 {
        score += fit * 10.0;
    }

    // Time horizon: early on, be conservative (favor spreading); late, pack tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * fit * 15.0;
    score -= progress * (1.0 - fit) * 20.0;

    // Global state: many open bins with high mean residual -> prefer reusing them
    let open = open_bins_count as f64;
    score -= (mean_residual / cap) * (open / (open + 5.0)) * 10.0;

    // New-bin candidate: penalize opening a new bin unless existing residuals are poor fits
    if bin_residual == bin_capacity {
        let base = 45.0 + fit * 20.0;
        let escape = if mean_residual < item_size as f64 { -35.0 } else { 0.0 };
        score += base + escape - progress * 10.0;
    }

    // Exact fit celebration
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste grows quadratically in normalized residual, modulated by progress
    let mut score = pr * (1.0 + 1.5 * progress * norm_pr);

    // Cubic dead-space penalty for tiny residuals late in stream
    score += 40.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Tight fits rewarded: fraction of bin filled by this item
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * (1.0 + progress);

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let combo = (item_size as f64 + next_item_size as f64) / cap;
        score -= 25.0 * combo * (0.5 + progress);
    } else if next_item_size > 0 {
        // next item won't fit: penalize proportionally to how close it was
        let miss = (next_item_size as f64 - pr) / cap;
        score += 12.0 * miss * miss;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    }

    // Penalize when bin residual deviates from mean residual (keeps bins homogeneous)
    score += 0.3 * (pr - mean_residual).abs();

    // Mild pressure against proliferating bins late in the stream
    score += (open_bins_count as f64) * 0.5 * (1.0 - progress);

    // New-bin candidate: make it attractive only when item is large and no good fit exists
    if bin_residual == bin_capacity {
        let new_bin_bonus = 20.0 * (1.0 - fill) - 15.0 * fill * progress;
        score += new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: residuals in [0..=5] are near-perfect closings,
    // [6..=15] awkward dead space, [16..=49] still usable for medium items, >=50 half-full.
    let cls = match post_residual {
        0..=5 => 0,
        6..=15 => 1,
        16..=49 => 2,
        _ => 3,
    };
    score += match cls {
        0 => -18.0,
        1 => 10.0,
        2 => 0.0,
        _ => -4.0,
    };

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // small item sizes (5,10,20,25) remain reusable — reward them.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        // Prime-ish awkward residuals penalized mildly.
        let r = post_residual;
        if r % 7 != 0 && r % 3 != 0 && r % 2 != 0 { score += 2.0; }
    }

    // Lookahead: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // Harmonic alignment: next item divides residual nicely
            if post_residual % next_item_size.max(1) == 0 { score -= 6.0; }
        } else {
            // next item won't fit here; residual becomes dead unless large enough
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish score that is
    // only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Opening cost grows with number of open bins and stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 20.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
        // If current item is large, a fresh bin is natural.
        if item_size >= 50 { score -= 12.0; }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity { score -= 5.0; }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (concentrate filling), unless the mean is tiny.
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 5.0 * dev;
    }

    score
}

