        if next_item_size as f64 > mean_residual * 1.4 && total_items.saturating_sub(step_index) > 100 {
            score -= 9.0;
        }
        if next_item_size <= item_size && item_size as f64 >= cap * 0.5 {
            score -= 25.0;
        }
        let any_fits_next = fitting_bins_count > 0 && mean_residual >= next_item_size as f64;
        if !any_fits_next && next_item_size > 0 && open_bins_count > 0 {
            score -= 18.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 24.0;
        }
        let remaining = total_items.saturating_sub(step_index);
        if remaining < 50 && open_bins_count > 0 {
            score += 35.0;
        }
        if item_size as f64 >= cap * 0.8 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        if r > 0 && r < next_item_size && r < 12 {
            score -= 20.0;
        }
        if item_size as f64 >= cap * 0.85 {
            score -= 12.0;
        }
        if open_bins_count > 6 && mean_residual > next_item_size as f64 * 1.5 {
            score += 18.0;
        }
        if next_item_size > 0 && item_size as f64 > cap * 0.7 && (cap - item_size as f64) < next_item_size as f64 {
            score -= 20.0;
        }
        // NEW: late-stream hard consolidation — near the end, strongly
        // discourage opening fresh bins when any open bin fits.
        if remaining < 120 && fitting_bins_count > 0 {
            score += 45.0;
        }
        // NEW: mid-stream, prefer fresh bin when the best open-bin placement
        // would leave a residual below the smallest plausible reuse band
        // while plenty of stream remains to use fresh capacity.
        if remaining > 300 && fitting_bins_count > 0 && r > 0 && r < next_item_size {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
