pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let r = post_residual;

    // Fill ratio of this placement: strongly reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.95 {
        score -= 22.0;
    } else if fill_ratio > 0.85 {
        score -= 9.0;
    } else if fill_ratio > 0.75 {
        score -= 3.0;
    }

    if r == 0 {
        score -= 950.0; // perfect fit
    } else if r < 10 {
        score += 70.0; // dead space below min item
    } else {
        if r % 10 == 0 {
            score -= 15.0;
        } else if r % 25 == 0 {
            score -= 11.0;
        } else if r % 5 == 0 {
            score -= 4.0;
        } else {
            score += 10.0;
        }
        // Mid-range residuals are highly usable by typical item sizes.
        if r >= 15 && r <= 45 {
            score -= 7.0;
        }
        // Penalize residuals too small for the upcoming item.
        if r < next_item_size {
            score += (next_item_size - r) as f64 * 3.0;
        }
    }

    // Fill-level coupling: reward near-closed bins.
    let fill = (bin_residual as f64) / cap;
    if fill >= 0.92 {
        score -= 28.0;
    } else if fill >= 0.9 {
        score -= 21.0;
    } else if fill >= 0.7 {
        score -= 9.0;
    } else if fill < 0.28 {
        score += 9.0;
    }

    // Lookahead couplings with graded rewards.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
