        // reusable window, since small items commonly refill these gaps.
        if pr >= nxt && (r - next_item_size) % 10 == 0 && pr - nxt <= 40.0 {
            score -= 8.0;
        }
        // Two-step lookahead: post-residual that can hold next item plus
        // half of it again is a strong consolidation signal.
        if pr >= nxt * 1.5 && pr < nxt * 2.0 && (pr - nxt * 1.5) < 5.0 {
