        }
        // Early stream, avoid stranding residual space.
        if remaining > 300 && fitting_bins_count > 0 && r > 0 && r < next_item_size {
            score += 11.0;
        }
        // NEW: mid-stream, prefer opening a bin when open bins are nearly full
        // and the next item would otherwise be stranded.
        if progress > 0.2 && progress < 0.85 && avg_open_fill > 0.8 && next_item_size as f64 > mean_residual {
