pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills, but weight dead space more for large residuals.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // --- 2-step lookahead: exact match of next item into the leftover space ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item also fits here: reward proportionally to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 35.0 * fill;
        } else {
            // Next item does NOT fit the leftover: penalize creating unusable-for-next space.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(40.0);
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // --- Last chance bonus: if this is the only bin that can fit the item, use it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if the item leaves a huge hole elsewhere
        // or existing bins are badly fragmented (high mean residual).
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 55.0; // default: prefer existing bins
        score -= 40.0 * fragmentation;
        if post_residual > 55 {
            score -= 25.0; // large item leaving big residual: fresh bin keeps space clean
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can also host the next item
        }
    }

    // --- Contextual pressure: many open bins with slack -> consolidate ---
    if open_bins_count > 3 && post_residual < (mean_residual as u32) {
        score -= 8.0;
    }

    // Late in the stream, tighten up: avoid scattering residual space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize opening a new bin when other bins could fit,
    // unless the fit is exceptionally tight elsewhere (handled below).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 60.0 + 0.25 * open_bins_count as f64;
    }

    // Reward tight fits: small post_residual is already favored by base term.
    // Extra reward when the leftover is dead space (too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // hard-to-fill zone
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Perfect pairing bonus: next item exactly consumes the remainder.
        if post_residual == next_item_size {
            score -= 18.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // If leftover can't host next item, penalize proportionally to waste.
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Prefer bins with residual below the mean (consolidate fullness),
    // spreading lightly-filled bins is worse for future items.
    score += 0.10 * (mean_residual - bin_residual as f64).abs().signum()
        * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more conservative about
    // fragmenting bins (favor tight fits more); late, just fill anything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let tightness_weight = 1.0 + 1.5 * (1.0 - progress);
    score *= 0.5 + 0.5 * tightness_weight * (1.0 - post_residual as f64 / bin_capacity as f64)
        + 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Fill-factor shaping: reward high occupancy ratio nonlinearly.
    let occupancy = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * occupancy * occupancy;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Base: penalize wasted residual, more strongly early in the stream
    let mut score = post * (0.6 + 0.8 * prog2);

    // Non-linear interaction: quadratic in normalized post residual
    score += 30.0 * norm_post * norm_post * (1.0 - progress);

    // Reward tight fits: cubic decay of post residual
    score -= 40.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);

    // Lookahead coupling: smooth interaction with next item size
    let norm_next = next_item_size as f64 / cap;
    let lookahead_fit = if next_item_size > 0 {
        let gap = (norm_post - norm_next).abs();
        (1.0 - gap).max(0.0)
    } else {
        0.5
    };
    score -= 25.0 * lookahead_fit * lookahead_fit * norm_post;

    // Mean residual deviation: smooth quadratic penalty
    let dev = (post - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - norm_post);
    } else {
        // Mild congestion penalty encouraging spreading
        score += 3.0 * (open_bins_count as f64).ln() * norm_item;
    }

    // Late-stream consolidation: prefer filling existing bins near the end
    score -= 20.0 * prog3 * (1.0 - norm_post);

    // New-bin candidate: penalize opening fresh bins unless residual is very tight
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) + 20.0 * norm_item;
    }

    score
}

