pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: modulo arithmetic on post_residual.
    // Leftovers that are "harmonically useful" (multiples of common small sizes)
    // are rewarded; awkward leftovers are penalized.
    let pr = post_residual as i64;
    if pr > 0 {
        // Perfect fit or tiny dead space: strong reward.
        if pr <= 2 {
            score -= 60.0;
        }
        // Harmonic classes: leftovers divisible by 25, 20, 10, 5 can host
        // typical item sizes exactly.
        if pr % 25 == 0 { score -= 18.0; }
        if pr % 20 == 0 { score -= 14.0; }
        if pr % 10 == 0 { score -= 10.0; }
        if pr % 5 == 0  { score -= 5.0; }
        // Awkward prime-ish leftovers in [1,9] are dead space: penalize.
        if pr < 10 && pr % 5 != 0 {
            score += 25.0;
        }
        // Medium awkward leftovers (11..19, non-multiples of 5) are half-dead.
        if pr >= 11 && pr <= 19 && pr % 5 != 0 {
            score += 10.0;
        }
    } else {
        // Exact fill is ideal.
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin is a perfect two-step chain.
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if pr == n {
            score -= 70.0;
        } else if pr > n {
            // Next item fits but leaves a remainder; reward harmonic remainders.
            let r2 = pr - n;
            if r2 % 10 == 0 { score -= 12.0; }
            if r2 % 5 == 0  { score -= 6.0; }
            score -= 4.0;
        } else {
            // Next item cannot use this bin: mild penalty scaled by waste class.
            let gap = (n - pr) as f64;
            score += gap * 0.5;
            // If next item is large and this bin would be nearly empty after,
            // keep the bin for it: penalize using it now.
            if n >= 50 && pr < 30 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits: post_residual already does this,
        // add a mild diversity bonus for keeping other bins flexible.
        score += (fitting_bins_count as f64).min(5.0);
    }

    // Fraction-of-capacity coupling: bins whose residual is a small fraction
    // of capacity are close to "sealed"; finishing them is good.
    let frac = post_residual as f64 / cap;
    score += frac * 20.0;

    // New-bin candidate logic: an empty bin (residual == capacity) should only
    // win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a new bin late in the stream is irrelevant; but if
        // many bins are open and none fit well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the item is large, a fresh bin avoids fragmenting open bins.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 25.0;
        }
        // Lookahead: large next item benefits from a fresh bin too.
        if next_item_size >= 50 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Stream progression: early on, be more willing to open bins (spread items);
    // late, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Mean residual coupling: if open bins are on average roomy, prefer filling
    // them rather than spreading; if mean residual is small, tighten fits.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Mild penalty for proliferating bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let r = post_residual;

    // Fill ratio of this placement: strongly reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.95 {
        score -= 22.0;
    } else if fill_ratio > 0.85 {
        score -= 9.0;
    } else if fill_ratio > 0.75 {
        score -= 3.0;
    }

    if r == 0 {
        score -= 950.0; // perfect fit
    } else if r < 10 {
        score += 70.0; // dead space below min item
    } else {
        if r % 10 == 0 {
            score -= 15.0;
        } else if r % 25 == 0 {
            score -= 11.0;
        } else if r % 5 == 0 {
            score -= 4.0;
        } else {
            score += 10.0;
        }
        if r >= 15 && r <= 45 {
            score -= 7.0;
        }
        if r < next_item_size {
            score += (next_item_size - r) as f64 * 3.0;
        }
    }

    // Fill-level coupling: reward near-closed bins.
    let fill = (bin_residual as f64) / cap;
    if fill >= 0.92 {
        score -= 28.0;
    } else if fill >= 0.9 {
        score -= 21.0;
    } else if fill >= 0.7 {
        score -= 9.0;
    } else if fill < 0.28 {
        score += 9.0;
    }

    // Lookahead couplings with graded rewards.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = r as f64;
        if pr == nxt {
            score -= 390.0;
            if fitting_bins_count <= 3 {
                score -= 40.0;
            }
        } else if pr >= nxt && pr - nxt <= 10.0 {
            score -= 145.0;
            if pr - nxt <= 8.0 {
                score -= 80.0;
            }
            if pr - nxt <= 3.0 {
                score -= 70.0;
            }
        } else if r > 0 && r < next_item_size {
            score += (nxt - pr) * 5.0;
        } else if pr >= nxt && (r - next_item_size) % 10 == 0 {
            score -= 26.0;
        }
        if pr >= nxt && pr - nxt >= 20.0 {
            score -= 10.0;
        }
        if pr > nxt && pr - nxt > 10.0 && pr - nxt < (nxt * 0.5).max(8.0) {
            score += 15.0;
        }
        if pr > 0.0 && pr < nxt * 0.35 {
            score += 7.0;
        }
        if pr > 0.0 && pr < nxt * 0.6 && pr >= nxt * 0.35 {
            score += 11.0;
        }
        // Two-item lookahead: residual that fits exactly two of the next item.
        if pr >= nxt && (pr - nxt) as u32 % next_item_size == 0 && pr - nxt > 0.0 {
            score -= 13.0;
        }
        if pr >= nxt && pr - nxt >= nxt && pr - nxt < 2.0 * nxt + 6.0 {
            score -= 22.0;
        }
        if pr > nxt * 1.5 && pr < nxt * 2.0 {
            score += 6.0;
        }
        // Exact k-multiple fit of the residual by the next item.
        if nxt > 0.0 && pr >= nxt && (pr as u32) % next_item_size == 0 {
            let k = (pr as f64 / nxt).round();
            if k >= 2.0 && k <= 4.0 {
                score -= 18.0 + 6.0 * (4.0 - k);
            }
        }
        if pr > nxt && pr - nxt > 0.0 && pr - nxt < 10.0 {
            score -= 6.0;
        }
        if pr > 0.0 && pr < nxt {
            score += (nxt - pr) * 2.0;
        }
        // Friendly (multiple of 5) mid-range residuals get reused.
        if pr >= 10.0 && pr <= 60.0 && (r % 5 == 0) {
            score -= 5.0;
        }
        if pr >= nxt && pr - nxt <= 2.0 {
            score -= 25.0;
        }
        if pr >= nxt * 0.7 && pr < nxt {
            score += 6.0;
        }
        if pr > 0.0 && pr < 8.0 && nxt > pr {
            score += 14.0 + 2.0 * (8.0 - pr);
        }
        if pr > 0.0 && pr < nxt {
            score += (mean_residual - pr) * 0.8;
        }
        if pr >= nxt && (pr as f64 - mean_residual).abs() <= 3.0 {
            score -= 9.0;
        }
        // COMBINED: fine-grained residual fitting + lookahead anticipation.
        if pr >= 5.0 && pr <= 100.0 {
            let band = (pr - nxt).abs();
            if band <= 1.0 {
                score -= 30.0;
            } else if band <= 4.0 {
                score -= 12.0;
            }
        }
        if pr > 0.0 && pr < nxt && fitting_bins_count > 2 {
            score += 8.0;
        }
        if pr > 0.0 && pr < nxt.min(15.0) {
            score += (nxt - pr) * 1.5;
        }
        if pr >= nxt && (r - next_item_size) % 10 == 0 && pr - nxt <= 40.0 {
            score -= 8.0;
        }
        // MUTATION: chain-aware lookahead — reward residuals that exactly fit the next
        // item when few bins can host it (chaining preserves tight-packing options).
        if pr >= nxt && (r % next_item_size.max(1)) == 0 {
            score -= 6.0;
            if fitting_bins_count <= 2 {
                score -= 10.0;
            }
        }
        // MUTATION: dead-zone penalty — residual too big to discard, too small to reuse.
        if pr >= 12.0 && pr < nxt && nxt > 20.0 {
            score += 4.0 + (nxt - pr) * 0.3;
        }
        // MUTATION: two-step lookahead — residual that fits next item plus a small
        // remainder matching a typical small item (< 10) is highly valuable.
        if pr > nxt && pr - nxt > 0.0 && pr - nxt < 10.0 && nxt >= 40.0 {
            score -= 14.0;
        }
        // MUTATION: penalize leaving residual that neither this stream nor next item
        // can ever use, scaled by remaining stream length.
        let remaining = total_items.saturating_sub(step_index);
        if pr > 0.0 && pr < nxt && remaining > 500 {
            score += 6.0;
        }
    }

    // Deviation from fleet mean: prefer bins that consolidate spare space.
    score += (mean_residual - bin_residual as f64) * 1.5;

    // Waste ratio of this placement.
    if item_size > 0 {
        let waste_ratio = r as f64 / (r + item_size) as f64;
        score += waste_ratio * 20.0;
    }

    // Fragmentation pressure.
    score += 2.2 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance / scarce-bin pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if fitting_bins_count <= 2 && r >= next_item_size && r > 0 {
        score -= 12.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_fill = 1.0 - mean_residual / cap;
        if avg_open_fill < 0.65 && progress > 0.08 {
            score += 55.0;
        } else {
            score += 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 55.0;
        }
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.6 {
            score -= 30.0;
        }
        if open_bins_count > 3 {
            score += 8.0;
        }
        if total_items.saturating_sub(step_index) > 200 && open_bins_count < 12 {
            score -= 12.0;
        }
        if (mean_residual - r as f64).abs() < 5.0 {
            score -= 10.0;
        }
        if next_item_size as f64 >= cap * 0.9 {
            score -= 15.0;
        }
        if next_item_size as f64 > mean_residual * 1.4 && total_items.saturating_sub(step_index) > 100 {
            score -= 9.0;
        }
        if next_item_size <= item_size && item_size as f64 >= cap * 0.5 {
            score -= 25.0;
        }
        let any_fits_next = fitting_bins_count > 0 && mean_residual >= next_item_size as f64;
        if !any_fits_next && next_item_size > 0 && open_bins_count > 0 {
            score -= 18.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 24.0;
        }
        let remaining = total_items.saturating_sub(step_index);
        if remaining < 50 && open_bins_count > 0 {
            score += 35.0;
        }
        if item_size as f64 >= cap * 0.8 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        if r > 0 && r < next_item_size && r < 12 {
            score -= 20.0;
        }
        if item_size as f64 >= cap * 0.85 {
            score -= 12.0;
        }
        if open_bins_count > 6 && mean_residual > next_item_size as f64 * 1.5 {
            score += 18.0;
        }
        if next_item_size > 0 && item_size as f64 > cap * 0.7 && (cap - item_size as f64) < next_item_size as f64 {
            score -= 20.0;
        }
        // Late-stream squeeze into existing bins.
        if remaining < 120 && fitting_bins_count > 0 {
            score += 45.0;
        }
