pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale waste non-linearly.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize leaving residual that is too small for typical future items.
        if post_residual < 10 {
            score += 8.0; // dead space penalty
