    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling of post-residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    let coupling = poly * (1.0 + 3.0 * progress);

    let mut score = pr;
    score -= 40.0 * coupling;

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= (1.0 - x) * (1.0 - x) * (20.0 + 30.0 * progress);

    // Penalize dead space relative to mean residual of open bins
    score += (x - mean_residual / cap).abs() * 10.0;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt).abs();
            score -= (1.0 - slack / cap) * 15.0;
        } else {
            score += (nxt - pr) / cap * 10.0;
