        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // next item cannot use this residual; residual is at risk of being dead.
        let waste = (post_residual as f64) / cap;
        score += waste * 10.0;
    }

    // Last chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin wastes the residual of this bin.
    // Penalize new bins unless current item is large and would leave a bad fit elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin baseline penalty grows with open bins (fragmentation pressure)
        score += 35.0 + open_bins_count as f64 * 0.5;
        // But if item is huge (harmonic class >= 3/4 of capacity) and residual of
        // other bins would be tiny, opening fresh is fine.
        if item_size as f64 >= 0.75 * cap {
            score -= 40.0;
        }
        // Late in stream, prefer consolidation into open bins
        score += progress * 15.0;
    }

    // Mild preference for fuller bins relative to the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // Gaps below the smallest plausible item (1..10) are pure waste; gaps just above a
    // typical small item are risky if they can't absorb the lookahead item.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0; // unusable dead space
        } else if post_residual < next_item_size as f64 && next_item_size > 0 {
            score += 15.0; // can't host the next item
        }
    } else {
        score -= 25.0; // perfect closure: reward exact fits strongly
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Penalize wasting a large residual on a small item
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && !new_bin {
        score -= 30.0;
    }

    // Lookahead synergy: reward residuals that can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
