pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / 50.0).max(0.0);
        // Penalize leaving residuals too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize large post_residual waste relative to smallest possible item (1)
    if post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins that tighten the residual distribution
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it when the item leaves a very poor residual everywhere.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 10.0; // pairing big item with fresh bin helps next item
        }
    }

    // Slight early-stream bias toward filling existing bins compactly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement;
    // if post-residual is too small for the next item, penalize.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in stream, be conservative with new bins (penalize fresh bins);
    // late in stream, allow tighter packing decisions.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress);
    }

    // Global state coupling: prefer filling bins below current mean residual
    // (reduces fragmentation relative to the fleet average).
    score += 0.35 * (mean_residual - post_residual as f64);

    // Slight penalty for spreading across many open bins when mean residual is high.
    if open_bins_count > 4 && mean_residual > 40.0 && bin_residual > item_size {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - progress) + x * (1.0 - x).powi(3) * progress;
    let mut score = post - 40.0 * poly * cap;

    // Reward tight fits smoothly (quartic in normalized fit quality)
    let fit_quality = 1.0 - x;
    score -= 25.0 * fit_quality * fit_quality * fit_quality * fit_quality;

    // Penalize dead space relative to mean residual, scaled by openness
    score += 0.05 * (post - mean_residual).abs() * (open_bins_count as f64).ln();

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fit_quality;
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            score += 8.0 * (nxt - post) / cap * (1.0 - progress);
        } else {
            score -= 6.0 * (1.0 - (post - nxt) / cap) * progress;
        }
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual as f64 == cap {
        score += 20.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: prefer post residuals that are
    // "composable" from common small item sizes (multiples of 10/20 classes).
    let class = (post_residual / 10) % 10;
    if class == 0 {
        score -= 6.0; // perfect harmonic class (0,10,20,...)
    } else if class == 5 {
        score -= 3.0; // half-class residuals are still usable
    } else {
        score += 2.0 + 0.3 * (class as f64); // odd/awkward residuals penalized
    }

    // Dead-space penalty: post_residual too small for the smallest item
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer tighter fits relative to mean residual
    score -= 0.5 * (mean_residual - post);

    // New-bin candidate: make empty bins attractive only when current fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 + 0.05 * open_bins_count as f64;
    }

    // Progress-based mild tightening: later in stream, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: post residual, with a strict dead-space penalty for unusable small gaps.
    score += post_residual as f64;

    // Dead space zone: residuals too small for the minimum item size are wasted.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 25.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: prefer using existing bins when many are open.
    score += open_bins_count as f64 * 2.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
        score -= next_fit * 20.0;
    }

    // Slight preference for bins below mean residual (balance residuals).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But allow opening when few bins exist and item is large.
        if open_bins_count == 0 {
            score -= 80.0;
        }
        if fill_ratio > 0.7 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into post_residual (good chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // Dead space: post_residual too small for next item and likely unusable.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Penalize tiny unusable leftovers relative to mean residual.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 12.0;
    } else if (post_residual as f64) > mean_residual {
        score -= 4.0;
    }
    // Last-chance bin: strongly favor filling it rather than leaving it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let base = 40.0
            + (open_bins_count as f64) * 2.0
            + (item_size as f64) * 0.3;
        // If the next item is huge and current item leaves a bad fit, new bin is fine.
        let lookahead_bonus = if next_item_size > 0 && post_residual < next_item_size {
            -10.0
        } else {
            0.0
        };
        score += base + lookahead_bonus;
    }
    // Progression: slightly tighten packing as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
