        if remaining > 300 && fitting_bins_count > 0 && r > 0 && r < next_item_size {
            score += 10.0;
        }
        if remaining > 800 && open_bins_count > 8 && fitting_bins_count > 0 {
            score += 14.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let min_dead = mean_residual.min(next_item_size as f64);
            if min_dead > 0.0 && min_dead < 5.0 && remaining > 200 {
                score -= 12.0;
            }
        }
        // prefer fresh bin when every fitting open bin would strand unusable dead space
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual > next_item_size as f64 {
            let slack = mean_residual - next_item_size as f64;
            if slack > 0.0 && slack < 8.0 && remaining > 150 {
                score -= 16.0;
            }
        }
        // late-stream: strongly resist opening bins when any bin fits
        if remaining < 80 && fitting_bins_count > 0 {
            score += 25.0;
        }
        // mid-stream consolidation: preserve scarce fitting capacity
        if remaining > 400 && fitting_bins_count > 0 && fitting_bins_count <= 2 && open_bins_count > 5 {
            score -= 10.0;
        }
        // MUTATION: endgame — avoid opening new bins when a mediocre fit exists
        if remaining < 30 && fitting_bins_count > 0 {
            score += 25.0;
        }
        // MUTATION: early-stream restraint — keep bin count low while plenty of stream remains
        if progress < 0.15 && open_bins_count > 2 && fitting_bins_count > 0 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Penalize dead space relative to capacity (non-linear)
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 40.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin normally,
    // but relax penalty when the fit in existing bins is poor
    if bin_residual == bin_capacity {
        let mut open_penalty = 25.0;
        // If item leaves very small residue elsewhere, new bin is bad
        if post_residual as f64 > mean_residual {
            open_penalty += 10.0;
        }
        // Lookahead: if next item is large, a fresh bin may be valuable
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if next_item_size as f64 > post_residual as f64 {
                // next item won't fit here anyway; new bin moderately OK
                open_penalty -= 8.0 + (next_item_size as f64 - post_residual as f64) * 0.1;
            } else {
                // next item could fit here; discourage new bin
                open_penalty += 12.0 - gap * 0.1;
            }
        }
        // Late in stream, avoid opening extra bins
        let t = step_index as f64 / total_items.max(1) as f64;
        open_penalty += t * 15.0;
        // Many open bins: discourage proliferation
        open_penalty += (open_bins_count as f64).sqrt() * 2.0;
        score += open_penalty;
    } else {
        // Existing bin: reward matching with mean residual (balanced usage)
        score += (post_residual as f64 - mean_residual).abs() * 0.3;
        // Lookahead synergy: if next item fits the post residual, big bonus
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 10.0 + (post_residual as f64 - next_item_size as f64).abs() * 0.2;
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 50.0;
        } else if post_residual < 10 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear interaction: waste pressure grows with stream progress
    let waste_term = norm_pr * norm_pr * (1.0 + 3.0 * progress) * cap;
    score += 0.5 * waste_term;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 8.0 * progress * tightness * item_size as f64;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Penalize bins with residuals far from mean residual (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + progress);

    // Lookahead coupling: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let compat = if pr >= ni { 1.0 - (pr - ni) / cap } else { 0.0 };
        score -= 5.0 * compat * (1.0 - progress);
    }

    // Mild penalty for opening new bins early, relaxes as stream progresses
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) * (1.0 + open_bins_count as f64 * 0.05);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition capacity into residue classes.
    // Class 0 (perfect fit) heavily rewarded; small dead-space classes penalized.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual as f64;

    if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    } else if post_residual <= eighth {
        // Dead space too small for typical items (min size 1..100, small slivers waste)
        if post_residual < 10 {
            score += 12.0; // unusable sliver
        } else {
            score += 4.0; // small but possibly usable
        }
    } else if post_residual <= quarter {
        score -= 6.0; // mid-small leftover, still useful
    } else {
        score -= 10.0; // large leftover stays flexible
    }

    // Harmonic matching: does post_residual accommodate the next item (k=2 lookahead)?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact harmonic: post_residual mod next_item_size == 0 => chain of perfect fits
            if next_item_size <= post_residual && post_residual % next_item_size == 0 {
                score -= 15.0;
            } else {
                score -= 8.0 * (post_residual as f64 / next_item_size as f64).min(2.0);
            }
        } else {
            // Next item won't fit here: leftover becomes dead unless near-zero
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible (huge dead space).
    if fitting_bins_count == 1 {
        score -= 10.0;
        if post_residual <= quarter {
            score -= 10.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and future items are large relative to residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = post_residual as f64 > quarter as f64 * 2.0; // wasted > half of item's fit
        if bad_fit && next_item_size > bin_residual.saturating_sub(post_residual) {
            score -= 20.0 * (0.5 + progress);
        } else {
            score += 15.0; // prefer existing bins by default
        }
    }

    // Mean residual coupling: when open bins are already loose, prefer tighter fills.
    score += (mean_residual - post as f64).max(0.0) * 0.05;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }
    // Small but potentially usable gaps: soft penalty proportional to unusability.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Open-bin pressure: prefer using existing bins over opening new ones.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if the next item fits in the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    }
    // Penalize leaving a gap that nearly fits but not quite for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Avoid wasting nearly-full bins; prefer filling large-residual bins with big items.
    score -= (bin_residual - item_size.min(bin_residual)) as f64 * 0.5;

    // Mild drift: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match => big bonus (subtract a lot)
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual as f64 >= next_item_size as f64 {
            // next item fits after placement: reward closeness
            score -= 25.0 / (1.0 + diff);
        } else {
            // next item won't fit: penalize, worse the smaller the leftover gap to next item
            score += 8.0 + 0.5 * diff;
        }
    }

    // Compare post_residual against mean residual: avoid creating tiny unusable slivers.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 && pr > 0.0 {
        // creating a sliver smaller than half the mean residual is wasteful
        score += (mean_residual * 0.5 - pr) * 0.8;
    } else if pr >= mean_residual {
        // keeping residual near/above mean keeps bins flexible
        score -= 3.0;
    }

    // Dead-space penalty: residuals that are too small to fit the smallest plausible item (1..100 unknown; use small threshold)
    if pr > 0.0 && pr < 10.0 {
        score += 20.0;
    }
    // Perfect closure bonus: fill the bin exactly
    if pr == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // Neutral-ish base; penalize opening new bins when many bins are open and fitting exists
        score += 5.0 + 0.3 * open_bins_count as f64;
        // But if the item is large relative to capacity, opening a fresh bin is fine
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild late-stream conservatism: as stream progresses, prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
