    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr / nxt).min(1.0);
        score -= 15.0 * fit_next * fit_next;
    } else {
        // Last item: pure waste minimization
        score += 5.0 * norm_pr;
    }

    // Mild penalty for opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 8.0 + 3.0 * open_bins_count as f64;
        // But allow new bin when mean residual is small (fragmented state)
        score -= 10.0 * (mean_residual / cap).clamp(0.0, 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
