    let min_item = 1.0;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < min_item {
        score += 50.0;
    }
    // Penalize residuals that are small but non-zero relative to capacity (fragmentation).
    let frag = (post_residual as f64) / (bin_capacity as f64);
    if frag > 0.0 && frag < 0.15 {
        score += 10.0 * (0.15 - frag);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 6.0;
    }
    // If next item would NOT fit here but would fit elsewhere, slight penalty for wasting the slot.
    if next_item_size > 0 && (next_item_size as f64) > post_residual as f64
        && (next_item_size as f64) <= bin_residual as f64 {
        score += 3.0;
    }

    // Global state: with many open bins, prefer consolidating into existing bins.
    let open_f = open_bins_count as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_f * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps bin population balanced, avoids extreme fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Slight preference for fuller bins overall.
    score -= 0.01 * (bin_capacity as f64 - bin_residual as f64);

    // New-bin candidate: make it moderately attractive only when open bins are fragmented
    // and the stream is early; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        let frag_pen = if mean_residual < 20.0 { 1.0 } else { 0.0 };
        score += 20.0 - 15.0 * early * frag_pen;
        // If next item is large and nothing fits well, a fresh bin is fine.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (pr / cap);

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large residuals more aggressively as stream advances (cubic term)
    score += (pr * pr / cap) * (0.3 * progress + 0.7 * progress * progress * progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 25.0 * (1.0 - (-3.0 * tightness).exp()) * (1.0 - 0.5 * progress);

    // Penalize dead space that cannot fit the next item (smooth quadratic coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0);
        score += 0.6 * (gap * gap) / cap;
        // Reward bins whose post-residual closely matches the next item (chain fit)
        score -= 12.0 * (-((pr - nxt) * (pr - nxt)) / (2.0 * 20.0 * 20.0)).exp();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + 0.5 * progress);
    }

    // Mild penalty proportional to crowding of open bins
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Penalize bins far below the mean residual (wasteful usage of roomy bins)
    score += 0.15 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction bands.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // fraction of capacity wasted

    // Dead-space penalty: strongly penalize residuals in "unusable" band (1..20 typical)
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (1.0 - frac * 5.0);
    }

    // Perfect fit reward: post_residual exactly 0 or a clean divisor class of capacity
    if post_residual == 0 {
        score -= 30.0;
    } else if bin_capacity % post_residual == 0 && post_residual <= 50 {
        // residual that can be tiled by equal items (harmonic class)
        score -= 12.0;
    }

    // Modulo arithmetic on residual: reward residuals in classes that future items likely hit
    let residue_class = post_residual % 10;
    score -= match residue_class {
        0 => 8.0,
        5 => 4.0,
        _ => 0.0,
    };

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item exactly tiles or fits
            score -= 10.0;
            if post_residual % next_item_size == 0 {
                score -= 8.0; // perfect tiling class
            }
        } else {
            // next item won't fit; this bin becomes dead space for the lookahead
            score += 6.0;
        }
    } else {
        // last item: minimize leftover
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets neutral baseline plus slight penalty
    if bin_residual == bin_capacity {
        // Prefer reusing bins unless the fit is bad; scale by stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = post_f + 25.0 - 10.0 * progress;
        // open new bin if current best fit would leave tiny dead space
        if item_size > 0 && bin_capacity - item_size < 15 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins overall (small residual before placement)
    score += (bin_residual as f64) * 0.05;

    // Mild penalty when many bins open and mean residual is high (fragmentation control)
    if open_bins_count > 1 {
        score += (mean_residual - post_f).abs() * 0.02;
    }

    score
}

