pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Prefer bins with below-average residual (more filled bins first).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= 0.8 * next_item_size as f64;
        } else {
            // next item cannot use the leftover; penalize dead space scaled by leftover size
            score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Compare post_residual relative to mean residual: prefer bins left near the mean
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize creating tiny unusable slivers (waste) unless perfectly matched
    if next_item_size > 0 && post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 150.0;
    }

    // Mild preference for keeping fewer open bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Slight preference for tighter fits generally
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (exact or near-exact fill).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 40.0;
    }

    // Penalize bins whose residual can't accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins can already fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + 2.0 * open_bins_count as f64;
        } else {
            // No existing bin fits: opening a new bin is necessary; slight
            // preference scaling with current bin count pressure.
            score -= 10.0;
        }
    }

    // Reward using bins with larger residuals (consume fragmented space).
    let res_frac = bin_residual as f64 / bin_capacity as f64;
    score += res_frac * 10.0;

    // Time-horizon modulation: early in the stream, be conservative with bins
    // (penalize waste more); later, allow looser fits.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Global state coupling: if mean residual is high, prefer consuming a
    // fragmented bin; if low, prioritize tight fits further.
    score -= (mean_residual / bin_capacity as f64 - res_frac) * 8.0;

    // Small penalty for item size relative to bin to bias large items into
    // emptier bins.
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}
